-- Vorrats-Aufgaben (rollend-14) in bestehende Flüge einfügen: 213 Aufgaben, 14 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (10, 'bruch.dezimal', 591, 24, $auf$[{"l": "stellenwerte", "t": "stellenwerte", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Dezimalzahl hat 4 Einer, 0 Zehntel, 7 Hundertstel und 5 Tausendstel. Wie viele Tausendstel sind das insgesamt?"}, "o": {"wert": 4075}, "h": "Wie viele Tausendstel sind 1 Einer? Wie viele Tausendstel sind 1 Hundertstel?", "w": "1 Einer sind 1 000 Tausendstel, also 4 Einer sind 4 000 Tausendstel. 1 Hundertstel sind 10 Tausendstel, also 7 Hundertstel sind 70. Dazu 5 Tausendstel: 4 000 + 70 + 5 = 4 075.", "form": "anwenden", "zaehlt": "ja", "r": 14592}, {"l": "stellenwerte", "t": "stellenwerte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Beim Weitsprung springt Sam 4,58 m. Kim springt 4,5 m. Um wie viele Zentimeter ist Sams Sprung weiter?"}, "o": {"wert": 8, "einheit": "cm"}, "h": "Rechne beide Weiten in Zentimeter um. 1 m sind 100 cm.", "w": "4,58 m = 458 cm und 4,5 m = 450 cm. Der Unterschied ist 458 − 450 = 8 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14593}, {"l": "stellenwerte", "t": "stellenwerte", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Aus den Ziffern 2, 5 und 8 wird eine Dezimalzahl gebildet. Jede Ziffer wird genau einmal benutzt, das Komma steht nach der ersten Ziffer. Um wie viele Hundertstel ist die größte solche Zahl größer als die kleinste?"}, "o": {"wert": 594, "einheit": "Hundertstel"}, "h": "Welche Ziffer muss vorne stehen, damit die Zahl möglichst groß oder möglichst klein ist? Dann ordnest du die restlichen Ziffern.", "w": "Größte Zahl: 8,52. Kleinste Zahl: 2,58. Unterschied: 8,52 − 2,58 = 5,94. Das sind 594 Hundertstel.", "form": "anwenden", "zaehlt": "ja", "r": 14594}, {"l": "vergleichen_ordnen", "t": "vergleichen_ordnen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Drei Päckchen wiegen 2,35 kg, 2,4 kg und 2,305 kg. Um wie viele Gramm ist das leichteste Päckchen leichter als das schwerste?"}, "o": {"wert": 95, "einheit": "g"}, "h": "Welches Päckchen ist am schwersten, welches am leichtesten? Fülle mit Endnullen auf: 2,400 und 2,305.", "w": "Am schwersten: 2,4 kg = 2 400 g. Am leichtesten: 2,305 kg = 2 305 g. Unterschied: 2 400 − 2 305 = 95 g.", "form": "anwenden", "zaehlt": "ja", "r": 14595}, {"l": "vergleichen_ordnen", "t": "vergleichen_ordnen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie viele Dezimalzahlen mit genau zwei Nachkommastellen liegen zwischen 0,4 und 0,5? Die Zahlen 0,4 und 0,5 selbst zählen nicht mit."}, "o": {"wert": 9}, "h": "Schreibe 0,4 als 0,40 und 0,5 als 0,50. Zähle die Hundertstel dazwischen.", "w": "0,40 sind 40 Hundertstel, 0,50 sind 50 Hundertstel. Dazwischen liegen 41 bis 49, das sind 9 Zahlen.", "form": "anwenden", "zaehlt": "ja", "r": 14596}, {"l": "vergleichen_ordnen", "t": "vergleichen_ordnen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Welche ist die kleinste Dezimalzahl mit genau zwei Nachkommastellen, die größer als 3,7 ist?"}, "o": {"wert": 3.71}, "h": "Schreibe 3,7 mit zwei Nachkommastellen: 3,70. Welche Zahl mit zwei Nachkommastellen kommt direkt danach?", "w": "3,7 = 3,70. Die nächste Zahl mit zwei Nachkommastellen ist 3,71. Sie ist größer als 3,70 und die kleinste solche Zahl.", "form": "anwenden", "zaehlt": "ja", "r": 14597}, {"l": "runden", "t": "runden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Wasserzähler zeigt 0,3846 m³. Runde auf Hundertstel. Wie viele Kubikmeter sind das gerundet?"}, "o": {"wert": 0.38, "einheit": "m³"}, "h": "Die Rundungsstelle ist die zweite Stelle nach dem Komma. Schau auf die Ziffer direkt rechts davon.", "w": "Hundertstel: 0,38. Die Ziffer rechts davon ist 4, also wird abgerundet. Ergebnis: 0,38 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14598}, {"l": "runden", "t": "runden", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim kauft 3 kg Äpfel. Ein Kilogramm kostet 1,748 €. Wie viel Euro kosten die Äpfel, gerundet auf ganze Cent?"}, "o": {"wert": 5.24, "einheit": "€"}, "h": "Rechne zuerst den genauen Preis aus. Dann rundest du auf Hundertstel.", "w": "3 · 1,748 = 5,244. Auf Hundertstel gerundet: Die Ziffer rechts ist 4, also abrunden. Ergebnis: 5,24 €.", "form": "anwenden", "zaehlt": "ja", "r": 14599}, {"l": "runden", "t": "runden", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Dezimalzahl mit zwei Nachkommastellen wird auf Zehntel gerundet. Das Ergebnis ist 4,3. Welche ist die größte Zahl, für die das gilt?"}, "o": {"wert": 4.34}, "h": "Bei der Ziffer 0 bis 4 an der Hundertstelstelle wird abgerundet. Welche Ziffer ist dort die größte?", "w": "Bis 4,34 wird auf 4,3 abgerundet. Ab 4,35 wird auf 4,4 aufgerundet. Die größte Zahl ist 4,34.", "form": "anwenden", "zaehlt": "ja", "r": 14600}, {"l": "bruch_zu_dezimal", "t": "bruch_zu_dezimal", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim trinkt 3/8 Liter Saft. Schreibe die Menge als Dezimalzahl."}, "o": {"wert": 0.375, "einheit": "l"}, "h": "Erweitere 3/8 auf den Nenner 1 000. Mit welcher Zahl musst du 8 malnehmen?", "w": "Erweitern mit 125: 3/8 = 375/1000 = 0,375. Probe: 3 : 8 = 0,375.", "form": "anwenden", "zaehlt": "ja", "r": 14601}, {"l": "bruch_zu_dezimal", "t": "bruch_zu_dezimal", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Stab ist 7/20 m lang. Wie viele Zentimeter sind das?"}, "o": {"wert": 35, "einheit": "cm"}, "h": "Erweitere 7/20 auf den Nenner 100. Dann siehst du die Hundertstel.", "w": "7/20 = 35/100 = 0,35 m. Das sind 0,35 · 100 = 35 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14602}, {"l": "bruch_zu_dezimal", "t": "bruch_zu_dezimal", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Dezimalzahl d hat denselben Wert wie 13/20. Wie groß ist d + 1/8?"}, "o": {"wert": 0.775}, "h": "Schreibe beide Brüche als Dezimalzahlen. Erweitere 13/20 auf Hundertstel und 1/8 auf Tausendstel.", "w": "13/20 = 65/100 = 0,65. 1/8 = 125/1000 = 0,125. Summe: 0,65 + 0,125 = 0,775.", "form": "anwenden", "zaehlt": "ja", "r": 14603}, {"l": "dezimal_zu_bruch", "t": "dezimal_zu_bruch", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Schnur ist 0,35 m lang. Schreibe 0,35 als vollständig gekürzten Bruch. Welche Zahl steht im Zähler?"}, "o": {"wert": 7}, "h": "0,35 sind 35/100. Kürze mit der größten Zahl, die in 35 und in 100 steckt.", "w": "0,35 = 35/100. Der größte gemeinsame Teiler ist 5. Gekürzt: 7/20. Im Zähler steht 7.", "form": "anwenden", "zaehlt": "ja", "r": 14604}, {"l": "dezimal_zu_bruch", "t": "dezimal_zu_bruch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Rezept braucht 0,625 kg Mehl. Wie viele Achtel Kilogramm sind das?"}, "o": {"wert": 5}, "h": "0,625 sind 625/1 000. Kürze mit 125. Welchen Nenner erhältst du?", "w": "0,625 = 625/1000 = 5/8. Das sind 5 Achtel Kilogramm. Probe: 5 · 0,125 = 0,625.", "form": "anwenden", "zaehlt": "ja", "r": 14605}, {"l": "dezimal_zu_bruch", "t": "dezimal_zu_bruch", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Kim schreibt: „0,075 = 75/100 = 3/4.“ Das ist falsch. Welchen Nenner hat der richtige, vollständig gekürzte Bruch?"}, "o": {"wert": 40}, "h": "Wie viele Nachkommastellen hat 0,075? Danach richtet sich der Nenner, bevor du kürzt.", "w": "0,075 hat 3 Nachkommastellen, also 75/1000. Kürzen mit 25 ergibt 3/40. Der Nenner ist 40.", "form": "anwenden", "zaehlt": "ja", "r": 14606}, {"l": "merkwerte", "t": "merkwerte", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Messbecher ist mit 1/8 Liter gefüllt. Wie viele Milliliter sind das?"}, "o": {"wert": 125, "einheit": "ml"}, "h": "Du weißt: 1/8 = 0,125. Ein Liter hat 1 000 ml.", "w": "1/8 l = 0,125 l. Das sind 0,125 · 1 000 = 125 ml.", "form": "anwenden", "zaehlt": "ja", "r": 14607}, {"l": "merkwerte", "t": "merkwerte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Sam hat 3/5 eines Buches mit 250 Seiten gelesen. Wie viele Seiten fehlen noch?"}, "o": {"wert": 100}, "h": "Du weißt: 1/5 = 0,2. Wie viele Seiten hat Sam gelesen? Dann ziehst du ab.", "w": "3/5 = 0,6. Gelesen: 0,6 · 250 = 150 Seiten. Es fehlen 250 − 150 = 100 Seiten.", "form": "anwenden", "zaehlt": "ja", "r": 14608}, {"l": "merkwerte", "t": "merkwerte", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Wie viel Prozent sind 1/4 + 0,125 + 3/5 zusammen?"}, "o": {"wert": 97.5, "einheit": "%"}, "h": "Schreibe jeden Summanden als Dezimalzahl: 1/4 = 0,25 und 3/5 = 0,6. Addiere. Dann rechnest du in Prozent um.", "w": "0,25 + 0,125 + 0,6 = 0,975. In Prozent: 0,975 · 100 = 97,5 %.", "form": "anwenden", "zaehlt": "ja", "r": 14609}, {"l": "periodisch", "t": "periodisch", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Sam teilt ein 10 m langes Band in 3 gleich lange Stücke. Wie lang ist ein Stück, gerundet auf Zentimeter?"}, "o": {"wert": 3.33, "einheit": "m"}, "h": "Rechne 10 : 3. Die Ziffer 3 wiederholt sich immer wieder. Runde auf Hundertstel.", "w": "10 : 3 = 3,3333… Die Ziffer 3 wiederholt sich. Auf Hundertstel gerundet: 3,33 m.", "form": "anwenden", "zaehlt": "ja", "r": 14610}, {"l": "periodisch", "t": "periodisch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Es gilt 4/11 = 0,363636… Die Ziffern 3 und 6 wechseln sich immer ab. Welche Ziffer steht an der 20. Stelle nach dem Komma?"}, "o": {"wert": 6}, "h": "An ungeraden Stellen steht 3, an geraden Stellen 6. Ist 20 gerade oder ungerade?", "w": "Die 1. Stelle ist 3, die 2. Stelle ist 6, und so weiter. Gerade Stellen haben die Ziffer 6. Die 20. Stelle ist gerade, also steht dort 6.", "form": "anwenden", "zaehlt": "ja", "r": 14611}, {"l": "periodisch", "t": "periodisch", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Es gilt 2/7 = 0,285714285714… Die Ziffernfolge 285714 wiederholt sich. Auf Tausendstel gerundet: Wie viele Tausendstel sind 2/7?"}, "o": {"wert": 286, "einheit": "Tausendstel"}, "h": "Schau auf die vierte Ziffer nach dem Komma. Sie entscheidet, ob du auf- oder abrundest.", "w": "0,2857… Die vierte Stelle ist 7, also wird aufgerundet. 0,286 sind 286 Tausendstel.", "form": "anwenden", "zaehlt": "ja", "r": 14612}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Sam schätzt das Ergebnis von 4,98 · 2,02. Dazu rundet er auf ganze Zahlen. Welchen Wert erhält er beim Überschlag?"}, "o": {"wert": 10}, "h": "Runde 4,98 und 2,02 auf ganze Zahlen. Dann multiplizierst du.", "w": "4,98 ≈ 5 und 2,02 ≈ 2. Überschlag: 5 · 2 = 10. Das genaue Ergebnis (10,0596) liegt nahe dabei.", "form": "anwenden", "zaehlt": "ja", "r": 14613}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Welche Dezimalzahl liegt genau in der Mitte zwischen 2,4 und 2,5?"}, "o": {"wert": 2.45}, "h": "Der Abstand zwischen 2,40 und 2,50 ist 0,10. Die Mitte liegt eine halbe Strecke von 2,40 entfernt.", "w": "Der Abstand ist 0,1. Die Hälfte davon ist 0,05. Die Mitte ist 2,4 + 0,05 = 2,45.", "form": "anwenden", "zaehlt": "ja", "r": 14614}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "begruenden", "y": "zahl", "f": {"text": "Kim behauptet: „Je mehr Ziffern nach dem Komma, desto größer ist die Zahl.“ Kim vergleicht 0,7 und 0,689. Um wie viele Tausendstel ist die Zahl mit weniger Ziffern größer?"}, "o": {"wert": 11, "einheit": "Tausendstel"}, "h": "Schreibe 0,7 als 0,700 und vergleiche mit 0,689 Stelle für Stelle.", "w": "0,7 = 0,700 = 700 Tausendstel. 0,689 sind 689 Tausendstel. Unterschied: 700 − 689 = 11 Tausendstel. Kims Aussage ist falsch.", "form": "anwenden", "zaehlt": "ja", "r": 14615}]$auf$::jsonb),
    (11, 'bruch.prozent', 621, 18, $auf$[{"l": "prozent_bedeutung", "t": "prozent_bedeutung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Der Ladebalken eines Tablets ist zu 3/5 gefüllt. Wie viel Prozent sind das?"}, "o": {"wert": 60, "einheit": "%"}, "h": "Prozent heißt Hundertstel. Erweitere den Bruch auf den Nenner 100.", "w": "3/5 = 60/100 (mit 20 erweitert). 60/100 sind 60 %. Der Akku ist zu 60 % geladen.", "form": "anwenden", "zaehlt": "ja", "r": 14622}, {"l": "prozent_bedeutung", "t": "prozent_bedeutung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Fruchtsaft besteht zu 35 % aus Orangensaft und zu 0,4 aus Apfelsaft. Der Rest ist Wasser. Wie viel Prozent des Safts sind Wasser?"}, "o": {"wert": 25, "einheit": "%"}, "h": "Schreibe alle Anteile als Prozentzahlen. Der ganze Saft sind 100 %.", "w": "0,4 = 40/100 = 40 %. Orangensaft und Apfelsaft zusammen: 35 % + 40 % = 75 %. Wasser: 100 % − 75 % = 25 %.", "form": "anwenden", "zaehlt": "ja", "r": 14623}, {"l": "prozent_bedeutung", "t": "prozent_bedeutung", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Wanderstrecke ist 80 m lang. Davon sind 0,25 asphaltiert und 15 % geschottert. Ein Fünftel der Strecke ist Wiese. Der Rest ist ein Waldweg. Wie viele Meter ist der Waldweg lang?"}, "o": {"wert": 32, "einheit": "m"}, "h": "Schreibe alle Anteile als Prozent. Wie viel Prozent bleiben für den Waldweg?", "w": "0,25 = 25 %, 15 %, 1/5 = 20 %. Zusammen 25 % + 15 % + 20 % = 60 %. Der Waldweg ist 40 % der Strecke: 40 % von 80 m = 0,4 · 80 = 32 m.", "form": "anwenden", "zaehlt": "ja", "r": 14624}, {"l": "prozentwert", "t": "prozentwert", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "In einer Schule mit 480 Kindern fahren 35 % mit dem Fahrrad zur Schule. Wie viele Kinder fahren mit dem Fahrrad?"}, "o": {"wert": 168, "einheit": "Kinder"}, "h": "Berechne zuerst 1 % der Kinder. Nimm das Ergebnis mal 35.", "w": "1 % von 480 sind 4,8 Kinder. 35 % sind 35 · 4,8 = 168 Kinder. Probe: 168 : 480 = 0,35.", "form": "anwenden", "zaehlt": "ja", "r": 14625}, {"l": "prozentwert", "t": "prozentwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Obsthändler hat 250 kg Äpfel. 12 % davon sind angefault und werden aussortiert. Wie viele Kilogramm Äpfel kann er verkaufen?"}, "o": {"wert": 220, "einheit": "kg"}, "h": "Berechne zuerst, wie viele Kilogramm aussortiert werden. Oder: Wie viel Prozent bleiben?", "w": "Aussortiert: 12 % von 250 kg = 30 kg. Es bleiben 250 − 30 = 220 kg. Oder: 88 % von 250 kg = 220 kg.", "form": "anwenden", "zaehlt": "ja", "r": 14626}, {"l": "prozentwert", "t": "prozentwert", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "In einem Chor mit 40 Kindern sind 60 % Mädchen. Von den Mädchen singen 25 % Alt. Wie viele Mädchen singen Alt?"}, "o": {"wert": 6, "einheit": "Mädchen"}, "h": "Bestimme zuerst, wie viele Mädchen im Chor sind. Von dieser Zahl nimmst du dann 25 %.", "w": "Mädchen: 60 % von 40 = 24. Davon 25 % = ein Viertel von 24 = 6. Sechs Mädchen singen Alt. Wichtig: Die 25 % beziehen sich auf die Mädchen, nicht auf alle 40 Kinder.", "form": "anwenden", "zaehlt": "ja", "r": 14627}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Noa löst in einem Test 34 von 40 Aufgaben richtig. Wie viel Prozent der Aufgaben hat Noa richtig gelöst?"}, "o": {"wert": 85, "einheit": "%"}, "h": "Teile die richtigen Aufgaben durch alle Aufgaben. Dann rechnest du in Prozent um.", "w": "34 : 40 = 0,85 = 85 %. Oder: 34/40 = 85/100 = 85 %.", "form": "anwenden", "zaehlt": "ja", "r": 14628}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Preis einer Eintrittskarte steigt von 250 € auf 280 €. Um wie viel Prozent ist der Preis gestiegen?"}, "o": {"wert": 12, "einheit": "%"}, "h": "Wie viel Euro ist der Preis gestiegen? Auf welchen Preis bezieht sich der Prozentsatz?", "w": "Die Erhöhung ist 280 − 250 = 30 €. Bezogen auf den alten Preis: 30 : 250 = 0,12 = 12 %.", "form": "anwenden", "zaehlt": "ja", "r": 14629}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Bei einer Umfrage unter 150 Kindern wählen 36 Kinder „Fußball“ und 45 Kinder „Schwimmen“. Alle anderen Kinder wählen „Sonstiges“. Wie viel Prozent der Kinder haben „Sonstiges“ gewählt?"}, "o": {"wert": 46, "einheit": "%"}, "h": "Wie viele Kinder haben „Sonstiges“ gewählt? Bezogen auf wie viele Kinder?", "w": "Sonstiges: 150 − 36 − 45 = 69 Kinder. 69 : 150 = 0,46 = 46 %. Kontrolle: Fußball 24 %, Schwimmen 30 %, Sonstiges 46 %, zusammen 100 %.", "form": "anwenden", "zaehlt": "ja", "r": 14630}, {"l": "grundwert", "t": "grundwert", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "In einem Orchester spielen 18 Kinder Geige. Das sind 30 % aller Kinder im Orchester. Wie viele Kinder spielen insgesamt im Orchester?"}, "o": {"wert": 60, "einheit": "Kinder"}, "h": "Wenn 30 % die Zahl 18 sind: Wie viele Kinder sind 1 %? Wie viele sind 100 %?", "w": "30 % sind 18 Kinder. 1 % sind 18 : 30 = 0,6 Kinder. 100 % sind 0,6 · 100 = 60 Kinder. Probe: 30 % von 60 = 18.", "form": "anwenden", "zaehlt": "ja", "r": 14631}, {"l": "grundwert", "t": "grundwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "In einem Wald sind 144 Bäume Buchen. Das sind 45 % aller Bäume. 15 % aller Bäume im Wald sind erkrankt. Wie viele Bäume sind erkrankt?"}, "o": {"wert": 48, "einheit": "Bäume"}, "h": "Berechne zuerst, wie viele Bäume es im Wald insgesamt gibt. Danach rechnest du mit 15 %.", "w": "45 % sind 144 Bäume, also 1 % = 3,2 Bäume und 100 % = 320 Bäume. 15 % von 320 = 48 Bäume sind erkrankt.", "form": "anwenden", "zaehlt": "ja", "r": 14632}, {"l": "grundwert", "t": "grundwert", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Dorf ist in den letzten Jahren um 12 % gewachsen. Heute hat es 1 120 Einwohner. Um wie viele Einwohner ist das Dorf gewachsen?"}, "o": {"wert": 120, "einheit": "Einwohner"}, "h": "Heute sind 112 % des früheren Werts. Berechne zuerst die frühere Einwohnerzahl.", "w": "Heute: 100 % + 12 % = 112 % sind 1 120 Einwohner. 1 % sind 10 Einwohner, 100 % sind 1 000. Gewachsen ist das Dorf um 1 120 − 1 000 = 120 Einwohner (12 % von 1 000).", "form": "anwenden", "zaehlt": "ja", "r": 14633}, {"l": "rabatt_aufschlag", "t": "rabatt_aufschlag", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Paar Schuhe kostet 60 €. Beim Schlussverkauf gibt es 15 % Rabatt. Wie viel Euro kosten die Schuhe jetzt?"}, "o": {"wert": 51, "einheit": "€"}, "h": "Wie viel Prozent vom alten Preis bezahlst du noch? Oder berechne den Rabatt in Euro und ziehe ihn ab.", "w": "Rabatt: 15 % von 60 € = 9 €. Neuer Preis: 60 − 9 = 51 €. Oder: 85 % von 60 € = 51 €.", "form": "anwenden", "zaehlt": "ja", "r": 14634}, {"l": "rabatt_aufschlag", "t": "rabatt_aufschlag", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Händler kauft einen Fernseher für 400 € ein und schlägt 30 % auf. Beim Verkauf gibt er dem Kunden 10 % Rabatt auf den Verkaufspreis. Wie viel Euro zahlt der Kunde?"}, "o": {"wert": 468, "einheit": "€"}, "h": "Berechne zuerst den Verkaufspreis nach dem Aufschlag. Der Rabatt bezieht sich auf diesen neuen Preis.", "w": "Aufschlag: 30 % von 400 € = 120 €, Verkaufspreis 520 €. Rabatt: 10 % von 520 € = 52 €. Der Kunde zahlt 520 − 52 = 468 €.", "form": "anwenden", "zaehlt": "ja", "r": 14635}, {"l": "rabatt_aufschlag", "t": "rabatt_aufschlag", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Alex zahlt für eine Jacke nach einem Rabatt von 25 % genau 90 €. Wie viel Euro hat Alex durch den Rabatt gespart?"}, "o": {"wert": 30, "einheit": "€"}, "h": "Die 90 € sind nicht 100 %. Wie viel Prozent des alten Preises sind 90 €? Berechne den alten Preis.", "w": "90 € sind 75 % des alten Preises. 1 % sind 1,20 €, 100 % sind 120 €. Gespart: 120 − 90 = 30 € (das sind 25 % von 120 €).", "form": "anwenden", "zaehlt": "ja", "r": 14636}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim sagt: „Beide Läden geben 20 % Rabatt auf eine Jacke, also spare ich in beiden Läden gleich viel.“ Im Laden A kostet die Jacke 80 €, im Laden B kostet sie 120 €. Wie viel Euro spart man in Laden B mehr als in Laden A?"}, "o": {"wert": 8, "einheit": "€"}, "h": "20 % sind immer 20 % von einem Preis. Berechne die Ersparnis für beide Jacken einzeln.", "w": "Laden A: 20 % von 80 € = 16 €. Laden B: 20 % von 120 € = 24 €. Unterschied: 24 − 16 = 8 €. Gleiche Prozentzahl heißt nicht gleich viel Euro, wenn die Preise verschieden sind.", "form": "anwenden", "zaehlt": "ja", "r": 14637}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Mannschaft A gewinnt 12 von 15 Spielen. Die Mannschaft B gewinnt 18 von 25 Spielen. Um wie viele Prozentpunkte ist der Anteil gewonnener Spiele bei A größer als bei B?"}, "o": {"wert": 8, "einheit": "Prozentpunkte"}, "h": "B hat mehr Spiele gewonnen, hat aber auch mehr gespielt. Vergleiche die Anteile in Prozent.", "w": "A: 12 : 15 = 0,8 = 80 %. B: 18 : 25 = 0,72 = 72 %. Unterschied: 80 − 72 = 8 Prozentpunkte. A gewinnt anteilig öfter, obwohl B mehr Siege hat.", "form": "anwenden", "zaehlt": "ja", "r": 14638}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Ein Preis von 50 € wird erst um 20 % erhöht. Danach wird der neue Preis um 20 % gesenkt. Kim sagt: „Dann ist der Preis wieder 50 €.“ Wie viel Euro kostet es wirklich am Ende?"}, "o": {"wert": 48, "einheit": "€"}, "h": "Die zweiten 20 % beziehen sich auf den neuen Preis, nicht auf 50 €. Rechne in zwei Schritten.", "w": "Erhöhung: 20 % von 50 € = 10 €, neuer Preis 60 €. Senkung: 20 % von 60 € = 12 €. Endpreis: 60 − 12 = 48 €. Der Preis ist niedriger als am Anfang, weil sich die zweiten 20 % auf den größeren Preis 60 € beziehen.", "form": "anwenden", "zaehlt": "ja", "r": 14639}]$auf$::jsonb),
    (31, 'stochastik.grundbegriffe', 590, 9, $auf$[{"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "In einer Lostrommel liegen Lose mit den Nummern 1 bis 20. Ein Los wird gezogen. Wie viele Ergebnisse gehören zum Ereignis „Die Nummer ist durch 5 teilbar“?"}, "o": {"wert": 4, "einheit": "Ergebnisse"}, "h": "Schreibe die Nummern auf, die durch 5 teilbar sind. Zähle sie.", "w": "Zu dem Ereignis gehören die Nummern 5, 10, 15 und 20. Das sind 4 Ergebnisse. Der Ergebnisraum hat 20 Ergebnisse.", "form": "anwenden", "zaehlt": "ja", "r": 14591}, {"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Würfel mit den Zahlen 1 bis 6 und eine Münze werden einmal geworfen. Ein Ergebnis ist ein Paar aus Zahl und Münzseite, zum Beispiel (5 | Wappen). Wie viele Ergebnisse gehören zum Ereignis „Die Würfelzahl ist größer als 4 oder die Münze zeigt Wappen“?"}, "o": {"wert": 8, "einheit": "Ergebnisse"}, "h": "Zähle zuerst die Ergebnisse mit Würfelzahl 5 oder 6. Zähle dann die Ergebnisse mit Wappen. Was wurde doppelt gezählt?", "w": "Würfelzahl größer als 4: (5 | W), (5 | Z), (6 | W), (6 | Z), das sind 4. Wappen: 6 Ergebnisse. Doppelt gezählt: (5 | W) und (6 | W), also 2. Zusammen 4 + 6 − 2 = 8. Probe: Nicht dazu gehören nur (1 bis 4 | Zahl), das sind 4 von 12 Ergebnissen.", "form": "anwenden", "zaehlt": "ja", "r": 14592}, {"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Glücksrad hat 20 gleich große Felder mit den Nummern 1 bis 20. Ereignis A: „Die Nummer ist ein Vielfaches von 4“. Ereignis B: „Die Nummer ist ein Vielfaches von 6“. Wie viele Ergebnisse gehören weder zu A noch zu B?"}, "o": {"wert": 13, "einheit": "Ergebnisse"}, "h": "Zähle die Vielfachen von 4 und die von 6. Achte auf Zahlen, die in beiden Gruppen vorkommen.", "w": "A: 4, 8, 12, 16, 20 – das sind 5. B: 6, 12, 18 – das sind 3. In beiden steht 12. A oder B: 5 + 3 − 1 = 7 Ergebnisse. Weder A noch B: 20 − 7 = 13. Probe: 13 Nummern bleiben übrig.", "form": "anwenden", "zaehlt": "ja", "r": 14593}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Sam wirft beim Training 40-mal einen Basketball auf den Korb und trifft 28-mal. Wie groß ist die relative Häufigkeit der Treffer in Prozent?"}, "o": {"wert": 70, "einheit": "%"}, "h": "Relative Häufigkeit = Zahl der Treffer geteilt durch Zahl der Versuche. Dann in Prozent umrechnen.", "w": "28 : 40 = 0,7. Als Prozent: 0,7 · 100 = 70 %. Sam trifft in 70 % der Fälle.", "form": "anwenden", "zaehlt": "ja", "r": 14594}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim würfelt in zwei Serien. In der ersten Serie sind es 50 Würfe, dabei fällt 18-mal die Sechs. In der zweiten Serie sind es 150 Würfe, dabei fällt 21-mal die Sechs. Wie groß ist die relative Häufigkeit der Sechs über beide Serien zusammen in Prozent?"}, "o": {"wert": 19.5, "einheit": "%"}, "h": "Zähle die Sechsen aller Würfe zusammen und teile durch die Zahl aller Würfe.", "w": "Sechsen: 18 + 21 = 39. Würfe: 50 + 150 = 200. Relative Häufigkeit: 39 : 200 = 0,195 = 19,5 %.", "form": "anwenden", "zaehlt": "ja", "r": 14595}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Spielerin A trifft bei 24 Würfen 18-mal. Spieler B trifft bei 40 Würfen 25-mal. Um wie viele Prozentpunkte ist die relative Häufigkeit der Treffer bei A größer als bei B?"}, "o": {"wert": 12.5, "einheit": "Prozentpunkte"}, "h": "Die Zahlen der Würfe sind verschieden. Vergleiche deshalb die relativen Häufigkeiten in Prozent.", "w": "A: 18 : 24 = 0,75 = 75 %. B: 25 : 40 = 0,625 = 62,5 %. Unterschied: 75 − 62,5 = 12,5 Prozentpunkte. A hat die höhere Trefferquote, obwohl B mehr Treffer hat.", "form": "anwenden", "zaehlt": "ja", "r": 14596}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "In einer Klasse mit 25 Kindern sind 14 Mädchen. 9 Kinder tragen eine Brille, darunter 5 Mädchen. Eine Vierfeldertafel zeigt: Mädchen mit Brille, Mädchen ohne Brille, Jungen mit Brille, Jungen ohne Brille. Wie viele Jungen tragen keine Brille?"}, "o": {"wert": 7, "einheit": "Jungen"}, "h": "Trage die bekannten Zahlen in eine Vierfeldertafel ein. Rechne zuerst die Zahl der Jungen und die der Jungen mit Brille aus.", "w": "Jungen: 25 − 14 = 11. Jungen mit Brille: 9 − 5 = 4. Jungen ohne Brille: 11 − 4 = 7. Probe: Mädchen mit Brille 5 + Mädchen ohne Brille 9 + Jungen mit Brille 4 + Jungen ohne Brille 7 = 25.", "form": "anwenden", "zaehlt": "ja", "r": 14597}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Bei einem Spiel wird zuerst ein Würfel mit den Zahlen 1 bis 6 geworfen. Bei einer geraden Zahl wird danach eine Münze geworfen. Bei einer ungeraden Zahl wird danach ein Würfel mit den Zahlen 1 bis 4 geworfen. Das Spiel wird als Baumdiagramm gezeichnet. Wie viele Wege hat es?"}, "o": {"wert": 18, "einheit": "Wege"}, "h": "Wie viele Äste gehen von der ersten Verzweigung aus? Zähle für jede Gruppe die Wege getrennt.", "w": "Gerade Zahlen: 2, 4, 6 – das sind 3, dann 2 Münzseiten: 3 · 2 = 6 Wege. Ungerade Zahlen: 1, 3, 5 – das sind 3, dann 4 Zahlen: 3 · 4 = 12 Wege. Zusammen 6 + 12 = 18 Wege.", "form": "anwenden", "zaehlt": "ja", "r": 14598}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "In einer Gruppe von 60 Personen sind 36 Frauen. 20 Personen kommen mit dem Rad. Unter den Radfahrern sind genauso viele Frauen wie Männer. Wie viele Frauen kommen nicht mit dem Rad?"}, "o": {"wert": 26, "einheit": "Frauen"}, "h": "Zeichne eine Vierfeldertafel mit „Frau / Mann“ und „Rad / nicht Rad“. Wie viele Frauen fahren Rad?", "w": "Die 20 Radfahrer sind zur Hälfte Frauen: 10 Frauen. Frauen insgesamt: 36. Frauen ohne Rad: 36 − 10 = 26. Probe: Männer mit Rad 10, Männer ohne Rad 24 − 10 = 14, zusammen 10 + 26 + 10 + 14 = 60.", "form": "anwenden", "zaehlt": "ja", "r": 14599}]$auf$::jsonb),
    (52, 'messen.koerper_berechnung', 552, 15, $auf$[{"l": "quader", "t": "quader", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Für ein Kantenmodell aus Draht wird ein Würfel mit der Kantenlänge 7 cm gebaut. Jede Kante des Würfels ist ein Drahtstück. Wie viele Zentimeter Draht braucht man insgesamt?"}, "o": {"wert": 84, "einheit": "cm"}, "h": "Wie viele Kanten hat ein Würfel? Alle Kanten sind gleich lang.", "w": "Ein Würfel hat 12 Kanten, jede ist 7 cm lang. Draht: 12 · 7 = 84 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14553}, {"l": "quader", "t": "quader", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Aus einem 1,5 m langen Draht wird das Kantenmodell eines Quaders gebaut. Der Quader ist 12 cm lang, 8 cm breit und 5 cm hoch. Wie viele Zentimeter Draht bleiben übrig?"}, "o": {"wert": 50, "einheit": "cm"}, "h": "Wie viele Kanten gleicher Länge gibt es von jeder Sorte? Rechne zuerst in Zentimetern.", "w": "Von jeder Sorte (Länge, Breite, Höhe) gibt es 4 Kanten. Draht für das Modell: 4 · (12 + 8 + 5) = 4 · 25 = 100 cm. 1,5 m = 150 cm. Es bleiben 150 − 100 = 50 cm übrig.", "form": "anwenden", "zaehlt": "ja", "r": 14554}, {"l": "quader", "t": "quader", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Quader ist 9 cm lang und 6 cm breit. Sein Volumen ist 270 cm³. Wie viele Zentimeter Draht braucht man für ein Kantenmodell dieses Quaders?"}, "o": {"wert": 80, "einheit": "cm"}, "h": "Berechne zuerst die fehlende Höhe aus dem Volumen. Danach zählst du alle 12 Kanten.", "w": "Höhe: 270 : (9 · 6) = 270 : 54 = 5 cm. Von jeder Sorte gibt es 4 Kanten: 4 · (9 + 6 + 5) = 4 · 20 = 80 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14555}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Spielwürfel aus Holz mit der Kantenlänge 7 cm wird rundum lackiert. Wie groß ist die Fläche, die lackiert wird?"}, "o": {"wert": 294, "einheit": "cm²"}, "h": "Ein Würfel hat 6 gleich große Flächen. Wie groß ist eine Fläche?", "w": "Eine Fläche ist ein Quadrat: 7 · 7 = 49 cm². Sechs Flächen: 6 · 49 = 294 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14556}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Schrank ist ein Quader: 1,2 m breit, 0,5 m tief und 2 m hoch. Die Vorderseite, die beiden Seitenwände und die Decke werden gestrichen. Die Rückwand steht an der Wand, der Boden ist unten. Wie viele Quadratmeter werden gestrichen?"}, "o": {"wert": 5, "einheit": "m²"}, "h": "Welche Flächen werden gestrichen? Berechne jede einzeln, auch die beiden gleichen Seitenwände.", "w": "Vorderseite: 1,2 · 2 = 2,4 m². Zwei Seitenwände: 2 · (0,5 · 2) = 2 m². Decke: 1,2 · 0,5 = 0,6 m². Zusammen 2,4 + 2 + 0,6 = 5 m².", "form": "anwenden", "zaehlt": "ja", "r": 14557}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Quader ist 6 cm lang und 4 cm breit. Seine Oberfläche ist 148 cm² groß. Wie hoch ist der Quader in Zentimetern?"}, "o": {"wert": 5, "einheit": "cm"}, "h": "Die Oberfläche ist 2 · (l · b + l · h + b · h). Was bleibt übrig, wenn du die beiden Grundflächen abziehst?", "w": "Boden und Deckel: 2 · 6 · 4 = 48 cm². Der Rest 148 − 48 = 100 cm² sind die vier Seitenflächen: 2 · 6 · h + 2 · 4 · h = 20h. Also 20h = 100 und h = 5 cm. Probe: 2 · (24 + 30 + 20) = 148.", "form": "anwenden", "zaehlt": "ja", "r": 14558}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein offenes Schwimmbecken hat die Form eines Quaders: 10 m lang, 5 m breit und 2 m tief. Boden und die vier Wände werden gefliest. Wie viele Quadratmeter Fliesen werden gebraucht?"}, "o": {"wert": 110, "einheit": "m²"}, "h": "Das Becken hat oben keine Fläche. Berechne den Boden und die vier Wände, die Wände paarweise.", "w": "Boden: 10 · 5 = 50 m². Zwei lange Wände: 2 · (10 · 2) = 40 m². Zwei kurze Wände: 2 · (5 · 2) = 20 m². Zusammen 50 + 40 + 20 = 110 m².", "form": "anwenden", "zaehlt": "ja", "r": 14559}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Zimmer ist 6 m lang, 4 m breit und 2,5 m hoch. Die vier Wände werden gestrichen. Die Tür (2 m²) und das Fenster (3 m²) werden nicht gestrichen. Ein Eimer Farbe reicht für 12 m². Wie viele Eimer muss man mindestens kaufen?"}, "o": {"wert": 4, "einheit": "Eimer"}, "h": "Berechne die Fläche der vier Wände und ziehe Tür und Fenster ab. Teile durch 12 und überlege, wie viele ganze Eimer nötig sind.", "w": "Wände: 2 · (6 · 2,5) + 2 · (4 · 2,5) = 30 + 20 = 50 m². Ohne Tür und Fenster: 50 − 5 = 45 m². 45 : 12 = 3,75. Man braucht ganze Eimer, also 4 Eimer.", "form": "anwenden", "zaehlt": "ja", "r": 14560}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Regal ist ein Quader: 1,5 m breit, 0,6 m tief und 2 m hoch. Es hat keine Vorderseite. Rückwand: eine dünne Platte, 4 € je m². Boden, Decke und die beiden Seitenwände: Holz, 12 € je m². Wie viel Euro kosten alle Platten zusammen?"}, "o": {"wert": 62.4, "einheit": "€"}, "h": "Teile die Flächen nach dem Preis. Welche Flächen sind Holz, welche ist die dünne Platte?", "w": "Holz: Boden und Decke 2 · 1,5 · 0,6 = 1,8 m², zwei Seitenwände 2 · 0,6 · 2 = 2,4 m², zusammen 4,2 m². Preis: 4,2 · 12 = 50,4 €. Rückwand: 1,5 · 2 = 3 m², Preis: 3 · 4 = 12 €. Zusammen 50,4 + 12 = 62,4 €.", "form": "anwenden", "zaehlt": "ja", "r": 14561}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Zwei Holzwürfel mit je 2 cm Kantenlänge werden mit einer ganzen Fläche aufeinander geklebt. Wie groß ist die Oberfläche des neuen Körpers?"}, "o": {"wert": 40, "einheit": "cm²"}, "h": "Rechne die Oberflächen beider Würfel einzeln und ziehe die Klebefläche zweimal ab.", "w": "Ein Würfel: 6 · 4 = 24 cm². Beide: 48 cm². Die Klebefläche (4 cm²) liegt bei beiden Würfeln innen. Sie fällt zweimal weg: 48 − 2 · 4 = 40 cm². Kontrolle: Die neue Form hat 2 Quadrate (Enden) + 4 Rechtecke 2 mal 4 cm: 8 + 32 = 40.", "form": "anwenden", "zaehlt": "ja", "r": 14562}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Auf einen Quader (6 cm lang, 4 cm breit, 3 cm hoch) wird ein Würfel mit 2 cm Kantenlänge geklebt. Der Würfel liegt mit seiner ganzen Unterseite auf der oberen Fläche des Quaders. Wie groß ist die Oberfläche des neuen Körpers?"}, "o": {"wert": 124, "einheit": "cm²"}, "h": "Berechne beide Oberflächen einzeln. Wie groß ist die Fläche, an der beide Körper sich berühren?", "w": "Quader: 2 · (24 + 18 + 12) = 108 cm². Würfel: 6 · 4 = 24 cm². Berührfläche: 2 · 2 = 4 cm². Sie fällt beim Quader und beim Würfel weg: 108 + 24 − 2 · 4 = 124 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14563}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 3, "g": "begruenden", "y": "zahl", "f": {"text": "Aus einem Quader (5 cm lang, 4 cm breit, 3 cm hoch) wird an einer Ecke ein Würfel mit 2 cm Kantenlänge herausgesägt. Um wie viele Quadratzentimeter wird die Oberfläche des Körpers größer? Wird sie nicht größer, ist die Antwort 0."}, "o": {"wert": 0, "einheit": "cm²"}, "h": "Welche Flächen gehen an der Ecke verloren? Welche neuen Flächen entstehen im Ausschnitt? Vergleiche ihre Größen.", "w": "An der Ecke verschwinden 3 Quadrate des Quaders (je 2 · 2 = 4 cm²), zusammen 12 cm². Im Ausschnitt entstehen 3 neue Quadrate (je 4 cm²), zusammen 12 cm². Die Oberfläche bleibt gleich: 12 − 12 = 0 cm² mehr. Das gilt, solange der Würfel an einer Ecke herausgeschnitten wird.", "form": "anwenden", "zaehlt": "ja", "r": 14564}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim sagt: „Wenn man bei einem Würfel die Kante verdoppelt, wird auch die Oberfläche doppelt so groß.“ Ein Würfel hat die Kantenlänge 3 cm. Die Kante wird auf 6 cm verdoppelt. Wie groß ist die neue Oberfläche in cm²?"}, "o": {"wert": 216, "einheit": "cm²"}, "h": "Berechne die neue Oberfläche direkt mit der neuen Kante. Vergleiche mit der alten Oberfläche.", "w": "Neue Oberfläche: 6 · 6 · 6 = 216 cm². Alte Oberfläche: 6 · 3 · 3 = 54 cm². 216 : 54 = 4. Die Oberfläche wird 4-mal so groß, nicht 2-mal. Kims Aussage stimmt nicht.", "form": "anwenden", "zaehlt": "ja", "r": 14565}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Quader ist 4 cm lang, 3 cm breit und 2 cm hoch. Die Höhe wird auf 4 cm verdoppelt, Länge und Breite bleiben gleich. Um wie viele Quadratzentimeter wird die Oberfläche größer?"}, "o": {"wert": 28, "einheit": "cm²"}, "h": "Berechne die Oberfläche vorher und nachher. Bilde dann die Differenz.", "w": "Vorher: 2 · (12 + 8 + 6) = 52 cm². Nachher: 2 · (12 + 16 + 12) = 80 cm². Unterschied: 80 − 52 = 28 cm². Die Oberfläche wird nicht doppelt so groß.", "form": "anwenden", "zaehlt": "ja", "r": 14566}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Zwei Quader haben beide das Volumen 120 cm³. Quader A ist 10 cm lang, 4 cm breit und 3 cm hoch. Quader B ist 6 cm lang, 5 cm breit und 4 cm hoch. Um wie viele Quadratzentimeter ist die Oberfläche von A größer als die von B?"}, "o": {"wert": 16, "einheit": "cm²"}, "h": "Gleiches Volumen bedeutet nicht gleiche Oberfläche. Berechne beide Oberflächen einzeln.", "w": "A: 2 · (40 + 30 + 12) = 164 cm². B: 2 · (30 + 24 + 20) = 148 cm². Unterschied: 164 − 148 = 16 cm². Beide Volumina sind gleich (10 · 4 · 3 = 120 = 6 · 5 · 4), aber der gedrungenere Quader B hat die kleinere Oberfläche.", "form": "anwenden", "zaehlt": "ja", "r": 14567}]$auf$::jsonb),
    (59, 'terme.aufstellen', 534, 18, $auf$[{"l": "struktur", "t": "struktur", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim rechnet den Term 3 + x · 2, Sam rechnet den Term (3 + x) · 2. Beide setzen x = 4 ein. Um wie viel ist Sams Ergebnis größer als Kims Ergebnis?"}, "o": {"wert": 3}, "h": "Rechne beide Terme einzeln aus. Beachte: Klammern zuerst, dann Punkt vor Strich.", "w": "Kim: 3 + 4 · 2 = 3 + 8 = 11 (Punkt vor Strich). Sam: (3 + 4) · 2 = 7 · 2 = 14 (Klammer zuerst). Unterschied: 14 − 11 = 3.", "form": "anwenden", "zaehlt": "ja", "r": 14535}, {"l": "struktur", "t": "struktur", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne den Wert des Terms 36 : (x − 3) + 2 · x für x = 9. Beachte, welche Rechnungen zuerst kommen."}, "o": {"wert": 24}, "h": "Die Klammer kommt zuerst. Danach: Punktrechnung vor Strichrechnung. Zuletzt addierst du.", "w": "Klammer: 9 − 3 = 6. Dann 36 : 6 = 6 und 2 · 9 = 18. Zuletzt 6 + 18 = 24.", "form": "anwenden", "zaehlt": "ja", "r": 14536}, {"l": "struktur", "t": "struktur", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Kim berechnet für eine Zahl x den Term 2 + 3x, Sam berechnet den Term (2 + 3) · x. Für genau eine Zahl x kommen beide auf dasselbe Ergebnis. Welche Zahl ist x?"}, "o": {"wert": 1}, "h": "Fasse Sams Term zusammen: (2 + 3) · x. Wie viele x hat jeder Term, und was bleibt übrig?", "w": "Sams Term ist 5x. Kims Term ist 3x + 2. Beide sind gleich, wenn 3x + 2 = 5x ist. Das ist 2 = 2x, also x = 1. Probe: 2 + 3 · 1 = 5 und (2 + 3) · 1 = 5.", "form": "anwenden", "zaehlt": "ja", "r": 14537}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Handyvertrag kostet 5 € Grundgebühr im Monat und 0,05 € für jede Minute. Der Preis in Euro ist 5 + 0,05 · m, wobei m die Zahl der Minuten ist. Wie viel Euro kostet der Vertrag bei m = 120 Minuten?"}, "o": {"wert": 11, "einheit": "€"}, "h": "Setze m = 120 ein. Rechne Punktrechnung vor Strichrechnung.", "w": "5 + 0,05 · 120 = 5 + 6 = 11. Der Vertrag kostet 11 €.", "form": "anwenden", "zaehlt": "ja", "r": 14538}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Alex hat auf einem Konto 50 €. Das Guthaben in Euro wird nach t Wochen durch den Term 50 − 4 · (t + 2) angegeben. Wie viel Euro sind es nach t = 3 Wochen?"}, "o": {"wert": 30, "einheit": "€"}, "h": "Die Klammer kommt zuerst. Dann die Multiplikation, zuletzt die Subtraktion.", "w": "Klammer: 3 + 2 = 5. Dann 4 · 5 = 20. Dann 50 − 20 = 30. Alex hat 30 €.", "form": "anwenden", "zaehlt": "ja", "r": 14539}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Aus einem Tank laufen Liter ab. Nach t Minuten sind noch 120 − 3 · (2t + 5) Liter im Tank. Nach wie vielen Minuten sind noch genau 63 Liter im Tank?"}, "o": {"wert": 7, "einheit": "Minuten"}, "h": "Setze den Term gleich 63. Arbeite von außen nach innen rückwärts: Was kommt zuletzt, was zuerst?", "w": "120 − 3 · (2t + 5) = 63. Dann 3 · (2t + 5) = 57, also 2t + 5 = 19, 2t = 14 und t = 7. Probe: 2 · 7 + 5 = 19, 3 · 19 = 57, 120 − 57 = 63.", "form": "anwenden", "zaehlt": "ja", "r": 14540}, {"l": "uebersetzen", "t": "uebersetzen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim denkt sich die Zahl 8. Sie bildet die Summe aus dem Doppelten dieser Zahl und 7. Welches Ergebnis erhält Kim?"}, "o": {"wert": 23}, "h": "Übersetze Wort für Wort: das Doppelte der Zahl heißt 2 mal die Zahl. Dazu kommt 7.", "w": "Das Doppelte von 8 ist 2 · 8 = 16. Die Summe aus 16 und 7 ist 23. Als Term: 2x + 7 mit x = 8.", "form": "anwenden", "zaehlt": "ja", "r": 14541}, {"l": "uebersetzen", "t": "uebersetzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim übersetzt: „Das Doppelte der Differenz aus x und 4, dazu das Dreifache von x.“ Welchen Wert hat der Term für x = 10?"}, "o": {"wert": 42}, "h": "Die Differenz aus x und 4 heißt x − 4 (in dieser Reihenfolge). Davon das Doppelte braucht eine Klammer.", "w": "Term: 2 · (x − 4) + 3x. Für x = 10: 2 · 6 + 30 = 12 + 30 = 42.", "form": "anwenden", "zaehlt": "ja", "r": 14542}, {"l": "uebersetzen", "t": "uebersetzen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Rechteck ist x cm breit. Die Länge ist 5 cm länger als das Doppelte der Breite. Der Umfang beträgt 70 cm. Wie breit ist das Rechteck in Zentimetern?"}, "o": {"wert": 10, "einheit": "cm"}, "h": "Schreibe die Länge als Term mit x. Stelle den Umfang 2 · (Breite + Länge) auf.", "w": "Länge: 2x + 5. Umfang: 2 · (x + 2x + 5) = 2 · (3x + 5) = 6x + 10. Aus 6x + 10 = 70 folgt 6x = 60 und x = 10. Probe: Länge 25 cm, Umfang 2 · (10 + 25) = 70.", "form": "anwenden", "zaehlt": "ja", "r": 14543}, {"l": "sachsituation", "t": "sachsituation", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Lieferdienst berechnet 2,50 € Liefergebühr und 8 € für jede Pizza. Wie viel Euro kosten 3 Pizzen mit Lieferung?"}, "o": {"wert": 26.5, "einheit": "€"}, "h": "Die Liefergebühr zahlt man nur einmal. Die 8 € zahlt man für jede Pizza.", "w": "Die Pizzen kosten 3 · 8 = 24 €. Dazu kommt die Liefergebühr 2,50 €. Zusammen 24 + 2,50 = 26,50 €. Als Term: 2,5 + 8 · x mit x = 3.", "form": "anwenden", "zaehlt": "ja", "r": 14544}, {"l": "sachsituation", "t": "sachsituation", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Auf Kims Sparbuch liegen 120 €. Jede Woche kommen 15 € dazu. Nach der 4. Woche werden einmal 30 € abgehoben. Wie viel Euro sind nach 8 Wochen auf dem Sparbuch?"}, "o": {"wert": 210, "einheit": "€"}, "h": "Wie oft kommen 15 € dazu? Die 30 € werden nur einmal abgehoben.", "w": "Einzahlungen: 8 · 15 = 120 €. Startbetrag 120 €. Eine Abhebung: −30 €. Gesamt: 120 + 120 − 30 = 210 €.", "form": "anwenden", "zaehlt": "ja", "r": 14545}, {"l": "sachsituation", "t": "sachsituation", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Kletterhalle hat zwei Angebote. Gruppenkarte: 36 € Grundpreis und 4 € je Person. Einzelkarten: 10 € je Person. Ab wie vielen Personen ist die Gruppenkarte günstiger als die Einzelkarten?"}, "o": {"wert": 7, "einheit": "Personen"}, "h": "Stelle für beide Angebote einen Term auf. Wann sind beide gleich teuer? Ab wann ist die Gruppenkarte günstiger?", "w": "Gruppe: 36 + 4n. Einzeln: 10n. Gleich teuer: 36 + 4n = 10n, also 36 = 6n und n = 6. Bei 6 Personen kosten beide gleich viel (60 €). Erst bei 7 Personen ist die Gruppenkarte günstiger (64 € gegen 70 €).", "form": "anwenden", "zaehlt": "ja", "r": 14546}, {"l": "muster", "t": "muster", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Folge von Figuren aus Plättchen: Figur 1 hat 5 Plättchen, Figur 2 hat 9 Plättchen, Figur 3 hat 13 Plättchen. So geht es weiter. Wie viele Plättchen hat Figur 15?"}, "o": {"wert": 61, "einheit": "Plättchen"}, "h": "Um wie viele Plättchen wird es von Figur zu Figur mehr? Prüfe deinen Term mit Figur 1.", "w": "Es kommen immer 4 Plättchen dazu. Der Term ist 4n + 1. Probe: n = 1 gibt 5, n = 2 gibt 9, n = 3 gibt 13. Für n = 15: 4 · 15 + 1 = 61 Plättchen.", "form": "anwenden", "zaehlt": "ja", "r": 14547}, {"l": "muster", "t": "muster", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Im Kursraum werden Tische in einer Reihe zusammengeschoben. An einem Tisch sitzen 4 Kinder, an zwei zusammengeschobenen Tischen 6 Kinder, an drei Tischen 8 Kinder. So geht es weiter. Für 30 Kinder wird eine Tischreihe gebraucht. Wie viele Tische müssen zusammengeschoben werden?"}, "o": {"wert": 14, "einheit": "Tische"}, "h": "Wie viele Plätze kommen mit jedem weiteren Tisch dazu? Stelle den Term für n Tische auf.", "w": "Mit jedem Tisch kommen 2 Plätze dazu. Der Term ist 2n + 2. Probe: n = 1 gibt 4, n = 2 gibt 6. Aus 2n + 2 = 30 folgt 2n = 28 und n = 14 Tische.", "form": "anwenden", "zaehlt": "ja", "r": 14548}, {"l": "muster", "t": "muster", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Zwei Muster aus Plättchen: Muster A hat bei Figur n genau 4n + 2 Plättchen. Muster B hat bei Figur n genau 6n − 4 Plättchen. Bei welcher Figur haben beide Muster gleich viele Plättchen?"}, "o": {"wert": 3}, "h": "Setze die beiden Terme gleich. Bringe alle Glieder mit n auf eine Seite.", "w": "4n + 2 = 6n − 4. Auf beiden Seiten 4n abziehen: 2 = 2n − 4. Dann 4 addieren: 6 = 2n, also n = 3. Probe: 4 · 3 + 2 = 14 und 6 · 3 − 4 = 14.", "form": "anwenden", "zaehlt": "ja", "r": 14549}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Der Term 40 − 5t gibt an, wie viele Kilometer noch bis zum Ziel fehlen, wenn eine Wandergruppe t Stunden unterwegs ist. Wie viele Kilometer wandert die Gruppe in jeder Stunde?"}, "o": {"wert": 5, "einheit": "km"}, "h": "Wie ändert sich der Term, wenn t um 1 größer wird? Was bedeutet die Zahl vor dem t?", "w": "Wenn t um 1 wächst, wird 5t um 5 größer und der Term um 5 kleiner. Die Zahl vor dem t zählt pro Stunde: Die Gruppe wandert 5 km in jeder Stunde. Die 40 ist die Strecke am Anfang.", "form": "anwenden", "zaehlt": "ja", "r": 14550}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Höhe einer Kerze in Zentimetern ist nach t Stunden 24 − 2t. Nach wie vielen Stunden ist die Kerze ganz abgebrannt?"}, "o": {"wert": 12, "einheit": "Stunden"}, "h": "Die Kerze ist abgebrannt, wenn ihre Höhe 0 ist. Wann ist 24 − 2t gleich 0?", "w": "24 − 2t = 0 heißt 2t = 24, also t = 12. Nach 12 Stunden ist die Höhe 0. Probe: 24 − 2 · 12 = 0.", "form": "anwenden", "zaehlt": "ja", "r": 14551}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Kim übersetzt „das Doppelte der Summe aus x und 3“ in den Term 2x + 3. Der richtige Term ist 2 · (x + 3). Um wie viel unterscheiden sich die beiden Werte für x = 5?"}, "o": {"wert": 3}, "h": "Berechne beide Terme einzeln für x = 5. Was wird bei Kims Term nur einmal und was zweimal gerechnet?", "w": "Kims Term: 2 · 5 + 3 = 13. Richtiger Term: 2 · (5 + 3) = 16. Unterschied: 16 − 13 = 3. Der Fehler: Im richtigen Term wird auch die 3 verdoppelt, bei Kim nicht.", "form": "anwenden", "zaehlt": "ja", "r": 14552}]$auf$::jsonb),
    (93, 'messen.flaechen_vielecke', 375, 24, $auf$[{"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Fensterscheibe hat die Form eines Parallelogramms. Die Grundseite ist 45 cm lang, die Höhe beträgt 30 cm. Wie groß ist die Fläche der Scheibe?"}, "o": {"wert": 1350, "einheit": "cm²"}, "h": "Beim Parallelogramm ist die Fläche Grundseite mal Höhe. Die Höhe steht senkrecht auf der Grundseite.", "w": "A = g · h = 45 · 30 = 1 350 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14376}, {"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Banner hat die Form eines Parallelogramms. Die Grundseite ist 2,4 m lang, die Höhe ist 1,5 m. Der Stoff kostet 8 € je Quadratmeter. Wie viel Euro kostet der Stoff für das Banner?"}, "o": {"wert": 28.8, "einheit": "€"}, "h": "Berechne zuerst die Fläche in m². Dann rechnest du den Preis.", "w": "Fläche: 2,4 · 1,5 = 3,6 m². Preis: 3,6 · 8 = 28,80 €.", "form": "anwenden", "zaehlt": "ja", "r": 14377}, {"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Parallelogramm hat die Seiten 9 cm und 12 cm. Die Höhe zur 9-cm-Seite ist 8 cm. Wie groß ist die Höhe zur 12-cm-Seite?"}, "o": {"wert": 6, "einheit": "cm"}, "h": "Berechne zuerst die Fläche mit der Grundseite 9 cm. Dieselbe Fläche gilt auch für die Grundseite 12 cm.", "w": "Fläche: 9 · 8 = 72 cm². Mit der Grundseite 12 cm gilt: 72 : 12 = 6 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14378}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Segel ist ein Dreieck mit der Grundseite 7 m und der Höhe 4 m. Wie groß ist die Fläche des Segels?"}, "o": {"wert": 14, "einheit": "m²"}, "h": "Beim Dreieck rechnest du Grundseite mal Höhe und teilst dann durch 2.", "w": "Das Rechteck mit denselben Maßen hat 7 · 4 = 28 m². Das Dreieck ist halb so groß: 28 : 2 = 14 m².", "form": "anwenden", "zaehlt": "ja", "r": 14379}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Wimpelkette hat 8 gleiche Dreiecke aus Stoff. Jedes Dreieck hat die Grundseite 30 cm und die Höhe 40 cm. Wie viele Quadratzentimeter Stoff braucht man für alle Wimpel?"}, "o": {"wert": 4800, "einheit": "cm²"}, "h": "Berechne zuerst die Fläche eines Wimpels. Dann rechnest du mal 8.", "w": "Ein Wimpel: 30 · 40 : 2 = 600 cm². Alle 8 Wimpel: 8 · 600 = 4 800 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14380}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Dreieck hat die Grundseite 14 cm und die Höhe 5 cm. Ein zweites Dreieck hat denselben Flächeninhalt, aber die Grundseite 10 cm. Wie hoch ist das zweite Dreieck?"}, "o": {"wert": 7, "einheit": "cm"}, "h": "Das erste Dreieck hat die Fläche 14 · 5 : 2. Für das zweite gilt dieselbe Fläche mit der Grundseite 10 cm.", "w": "Fläche: 14 · 5 : 2 = 35 cm². Zweites Dreieck: 2 · 35 : 10 = 7 cm. Probe: 10 · 7 : 2 = 35.", "form": "anwenden", "zaehlt": "ja", "r": 14381}, {"l": "trapez", "t": "trapez", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Die Giebelwand eines Schuppens ist ein Trapez. Die parallelen Seiten sind 10 m und 6 m lang, die Höhe ist 3 m. Wie groß ist die Wandfläche?"}, "o": {"wert": 24, "einheit": "m²"}, "h": "Beim Trapez addierst du die parallelen Seiten, multiplizierst mit der Höhe und teilst durch 2.", "w": "(10 + 6) · 3 : 2 = 16 · 3 : 2 = 48 : 2 = 24 m².", "form": "anwenden", "zaehlt": "ja", "r": 14382}, {"l": "trapez", "t": "trapez", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Tischplatte hat die Form eines Trapezes. Die parallelen Seiten sind 1,2 m und 0,8 m lang, der Abstand zwischen ihnen ist 0,5 m. Lack kostet 12 € je Quadratmeter. Wie viel Euro kostet der Lack für die Platte?"}, "o": {"wert": 6, "einheit": "€"}, "h": "Berechne zuerst die Fläche der Platte. Dann rechnest du den Preis.", "w": "Fläche: (1,2 + 0,8) · 0,5 : 2 = 0,5 m². Preis: 0,5 · 12 = 6 €.", "form": "anwenden", "zaehlt": "ja", "r": 14383}, {"l": "trapez", "t": "trapez", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Trapez hat die Fläche 54 cm² und die Höhe 6 cm. Eine der parallelen Seiten ist 11 cm lang. Wie lang ist die andere parallele Seite?"}, "o": {"wert": 7, "einheit": "cm"}, "h": "Zweimal die Fläche geteilt durch die Höhe ist die Summe der parallelen Seiten.", "w": "Summe der parallelen Seiten: 2 · 54 : 6 = 18 cm. Die andere Seite: 18 − 11 = 7 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14384}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Parallelogramm hat die Fläche 96 cm² und die Grundseite 12 cm. Wie hoch ist es?"}, "o": {"wert": 8, "einheit": "cm"}, "h": "Die Fläche ist Grundseite mal Höhe. Teile die Fläche durch die Grundseite.", "w": "h = A : g = 96 : 12 = 8 cm. Probe: 12 · 8 = 96.", "form": "anwenden", "zaehlt": "ja", "r": 14385}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Dreieck hat die Fläche 60 cm² und die Höhe 8 cm. Wie lang ist die zugehörige Grundseite?"}, "o": {"wert": 15, "einheit": "cm"}, "h": "Beim Dreieck ist die Fläche g · h : 2. Rechne zuerst zweimal die Fläche.", "w": "2 · 60 = 120. Grundseite: 120 : 8 = 15 cm. Probe: 15 · 8 : 2 = 60.", "form": "anwenden", "zaehlt": "ja", "r": 14386}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Rechteck ist 6 cm breit und 10 cm lang. Ein Dreieck hat denselben Flächeninhalt und die Grundseite 15 cm. Wie hoch ist das Dreieck?"}, "o": {"wert": 8, "einheit": "cm"}, "h": "Berechne die Fläche des Rechtecks. Beim Dreieck rechnest du dann zweimal die Fläche geteilt durch die Grundseite.", "w": "Rechteck: 6 · 10 = 60 cm². Dreieck: 2 · 60 : 15 = 8 cm. Probe: 15 · 8 : 2 = 60.", "form": "anwenden", "zaehlt": "ja", "r": 14387}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Zimmer ist ein Rechteck von 8 m mal 5 m. An einer Seite hat es einen Erker, der ein Quadrat mit 2 m Seitenlänge ist. Wie groß ist die Bodenfläche mit dem Erker?"}, "o": {"wert": 44, "einheit": "m²"}, "h": "Zerlege den Grundriss in ein Rechteck und ein Quadrat. Berechne beide Flächen.", "w": "Rechteck: 8 · 5 = 40 m². Erker: 2 · 2 = 4 m². Zusammen 40 + 4 = 44 m².", "form": "anwenden", "zaehlt": "ja", "r": 14388}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Spielfeld ist ein Rechteck von 20 m mal 12 m. In einer Ecke liegt ein Beet in Form eines rechtwinkligen Dreiecks mit den Katheten 6 m und 4 m. Dort darf man nicht spielen. Wie groß ist die Spielfläche?"}, "o": {"wert": 228, "einheit": "m²"}, "h": "Berechne das ganze Rechteck. Ziehe dann die Fläche des Dreiecks ab. Das Dreieck ist halb so groß wie ein Rechteck mit denselben Maßen.", "w": "Rechteck: 20 · 12 = 240 m². Dreieck: 6 · 4 : 2 = 12 m². Spielfläche: 240 − 12 = 228 m².", "form": "anwenden", "zaehlt": "ja", "r": 14389}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Bild ist 40 cm breit und 30 cm hoch. Es hat einen Rahmen, der rundherum 5 cm breit ist. Wie groß ist die Fläche des Rahmens ohne das Bild?"}, "o": {"wert": 800, "einheit": "cm²"}, "h": "Der Rahmen macht das Rechteck auf jeder Seite größer. Berechne das Außenrechteck und ziehe das Bild ab.", "w": "Außen: (40 + 10) · (30 + 10) = 50 · 40 = 2 000 cm². Bild: 40 · 30 = 1 200 cm². Rahmen: 2 000 − 1 200 = 800 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14390}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Geschenk ist ein Quader: 20 cm lang, 10 cm breit und 5 cm hoch. Es wird rundherum in Papier eingepackt, ohne dass sich das Papier überlappt. Wie viele Quadratzentimeter Papier braucht man mindestens?"}, "o": {"wert": 700, "einheit": "cm²"}, "h": "Ein Quader hat drei Paare gleicher Flächen. Berechne jede Sorte einmal und verdopple die Summe.", "w": "Boden und Deckel: 20 · 10 = 200. Vorder- und Rückseite: 20 · 5 = 100. Die beiden Seiten: 10 · 5 = 50. Summe: 350. Doppelt: 700 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14391}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Aquarium aus Glas hat keinen Deckel. Es ist 50 cm lang, 30 cm breit und 40 cm hoch. Wie viele Quadratzentimeter Glas braucht man für Boden und vier Seitenwände?"}, "o": {"wert": 7900, "einheit": "cm²"}, "h": "Rechne den Boden und die vier Seitenwände getrennt. Es gibt zwei lange und zwei kurze Wände.", "w": "Boden: 50 · 30 = 1 500 cm². Lange Wände: 2 · 50 · 40 = 4 000 cm². Kurze Wände: 2 · 30 · 40 = 2 400 cm². Zusammen 1 500 + 4 000 + 2 400 = 7 900 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14392}, {"l": "oberflaeche", "t": "oberflaeche", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Würfel hat die Oberfläche 54 cm². Zwei solche Würfel werden mit je einer ganzen Fläche zu einem Quader zusammengeklebt. Wie groß ist die Oberfläche des Quaders?"}, "o": {"wert": 90, "einheit": "cm²"}, "h": "Wie groß ist eine Würfelfläche? Beim Zusammenkleben verschwinden zwei Würfelflächen.", "w": "Eine Würfelfläche: 54 : 6 = 9 cm². Beide Würfel: 2 · 54 = 108 cm². Beim Kleben verschwinden 2 · 9 = 18 cm². Oberfläche: 108 − 18 = 90 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14393}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Dreieck hat die Grundseite 8 cm und die Höhe 6 cm. Die Grundseite wird verdoppelt, die Höhe bleibt gleich. Wie groß ist die neue Fläche?"}, "o": {"wert": 48, "einheit": "cm²"}, "h": "Wie ändert sich die Fläche, wenn die Grundseite doppelt so lang wird? Du kannst auch neu rechnen.", "w": "Die neue Grundseite ist 16 cm. Fläche: 16 · 6 : 2 = 48 cm². Die Fläche hat sich verdoppelt (vorher 24 cm²).", "form": "anwenden", "zaehlt": "ja", "r": 14394}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Rechteck ist 9 cm lang und 6 cm hoch. Ein Parallelogramm hat dieselbe Grundseite 9 cm und dieselbe Höhe 6 cm. Seine schräge Seite ist 8 cm lang. Wie groß ist die Fläche des Parallelogramms?"}, "o": {"wert": 54, "einheit": "cm²"}, "h": "Beim Parallelogramm zählt die Höhe, nicht die schräge Seite. Die Höhe steht senkrecht auf der Grundseite.", "w": "Das Parallelogramm hat dieselbe Grundseite und Höhe wie das Rechteck. Gleiche Fläche: 9 · 6 = 54 cm². Die schräge Seite ist für die Fläche nicht wichtig.", "form": "anwenden", "zaehlt": "ja", "r": 14395}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Kim berechnet ein Trapez mit den parallelen Seiten 8 cm und 4 cm und der Höhe 5 cm so: „8 · 4 · 5 : 2 = 80 cm².“ Um wie viele Quadratzentimeter ist Kims Ergebnis zu groß?"}, "o": {"wert": 50, "einheit": "cm²"}, "h": "Welche Formel gilt beim Trapez? Berechne die richtige Fläche und vergleiche mit Kims 80.", "w": "Richtig: (8 + 4) · 5 : 2 = 30 cm². Kim hat die Seiten malgenommen statt addiert und kommt auf 80 cm². Unterschied: 80 − 30 = 50 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14396}, {"l": "drachen_raute", "t": "drachen_raute", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Papierdrache hat die Diagonalen 60 cm und 40 cm. Wie groß ist die Fläche des Drachens?"}, "o": {"wert": 1200, "einheit": "cm²"}, "h": "Beim Drachen rechnest du: erste Diagonale mal zweite Diagonale, geteilt durch 2.", "w": "A = e · f : 2 = 60 · 40 : 2 = 2 400 : 2 = 1 200 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14397}, {"l": "drachen_raute", "t": "drachen_raute", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Fliese hat die Form einer Raute mit den Diagonalen 18 cm und 10 cm. Zwei gleiche Fliesen liegen nebeneinander. Wie groß ist ihre gesamte Fläche?"}, "o": {"wert": 180, "einheit": "cm²"}, "h": "Berechne zuerst die Fläche einer Fliese. Dann verdoppelst du.", "w": "Eine Fliese: 18 · 10 : 2 = 90 cm². Zwei Fliesen: 2 · 90 = 180 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14398}, {"l": "drachen_raute", "t": "drachen_raute", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Raute hat die Fläche 120 cm². Die eine Diagonale ist 24 cm lang. Wie lang ist die andere Diagonale?"}, "o": {"wert": 10, "einheit": "cm"}, "h": "Die Fläche ist e · f : 2. Rechne zuerst zweimal die Fläche. Dann teilst du durch die bekannte Diagonale.", "w": "2 · 120 = 240. Andere Diagonale: 240 : 24 = 10 cm. Probe: 24 · 10 : 2 = 120.", "form": "anwenden", "zaehlt": "ja", "r": 14399}]$auf$::jsonb),
    (94, 'messen.prisma_zylinder', 411, 21, $auf$[{"l": "prisma_volumen", "t": "prisma_volumen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Für eine Wasserleitung wird ein Graben ausgehoben. Sein Querschnitt ist ein Trapez: oben 3 m breit, unten 1 m breit und 2 m tief. Der Graben ist 25 m lang. Wie viele Kubikmeter Erde werden ausgehoben?"}, "o": {"wert": 100, "einheit": "m³"}, "h": "Der Graben ist ein Prisma. Die Grundfläche ist der trapezförmige Querschnitt. Berechne zuerst seine Fläche.", "w": "Querschnitt: (3 + 1) : 2 · 2 = 4 m². Volumen = Grundfläche · Länge = 4 · 25 = 100 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14412}, {"l": "prisma_volumen", "t": "prisma_volumen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Betonprofil ist 2 m lang. Sein Querschnitt hat die Form eines L: Der Fuß ist 30 cm breit und 10 cm hoch. Darauf steht ein Steg, der 10 cm breit und 30 cm hoch ist. Fuß und Steg überlappen sich nicht. Wie viele Kubikdezimeter Beton enthält das Profil?"}, "o": {"wert": 120, "einheit": "dm³"}, "h": "Rechne die Fläche des Querschnitts aus zwei Rechtecken. Achte auf die Einheiten: 1 dm³ = 1 000 cm³.", "w": "Querschnitt: 30 · 10 + 10 · 30 = 600 cm². Länge: 2 m = 200 cm. Volumen: 600 · 200 = 120 000 cm³ = 120 dm³. Probe in dm: Querschnitt 6 dm², Länge 20 dm, 6 · 20 = 120.", "form": "anwenden", "zaehlt": "ja", "r": 14413}, {"l": "prisma_volumen", "t": "prisma_volumen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Dreiecksprisma hat als Grundfläche ein Dreieck mit der Grundseite 9 cm und der Höhe 6 cm. Sein Volumen ist genauso groß wie das Volumen eines Würfels mit der Kantenlänge 6 cm. Wie hoch ist das Prisma?"}, "o": {"wert": 8, "einheit": "cm"}, "h": "Berechne zuerst das Volumen des Würfels und die Grundfläche des Dreiecks. Danach brauchst du die fehlende Größe des Prismas.", "w": "Würfel: 6³ = 216 cm³. Dreieck: 9 · 6 : 2 = 27 cm². V = G · h, also h = 216 : 27 = 8 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14414}, {"l": "prisma_oberflaeche", "t": "prisma_oberflaeche", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Holzprisma wird komplett lackiert. Seine Grundfläche ist ein rechtwinkliges Dreieck mit den Seiten 6 cm, 8 cm und 10 cm. Das Prisma ist 15 cm hoch. Wie viele Quadratzentimeter müssen lackiert werden?"}, "o": {"wert": 408, "einheit": "cm²"}, "h": "Die Oberfläche besteht aus zwei Grundflächen und dem Mantel. Der Mantel ist ein Rechteck: Umfang der Grundfläche mal Höhe.", "w": "Grundfläche: 6 · 8 : 2 = 24 cm². Zwei Grundflächen: 48 cm². Umfang: 6 + 8 + 10 = 24 cm. Mantel: 24 · 15 = 360 cm². O = 48 + 360 = 408 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14415}, {"l": "prisma_oberflaeche", "t": "prisma_oberflaeche", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Blumenkasten ist 100 cm lang. Sein Querschnitt ist ein gleichschenkliges Trapez: unten (Boden) 40 cm breit, oben (offen) 70 cm breit, 20 cm hoch, die schrägen Seiten sind je 25 cm lang. Die obere Seite ist offen, es gibt dort keinen Deckel. Wie viele Quadratzentimeter Blech braucht man für Boden, beide Seitenwände und beide Stirnseiten?"}, "o": {"wert": 11200, "einheit": "cm²"}, "h": "Die Stirnseiten sind die beiden Trapeze. Die Länge 100 cm gilt für Boden und beide schräge Seitenwände. Die Höhe 20 cm ist nicht die Länge der schrägen Seite.", "w": "Ein Trapez: (40 + 70) : 2 · 20 = 1 100 cm², zwei Stirnseiten: 2 200 cm². Boden: 40 · 100 = 4 000 cm². Schräge Seitenwände: 2 · 25 · 100 = 5 000 cm². Zusammen: 2 200 + 4 000 + 5 000 = 11 200 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14416}, {"l": "prisma_oberflaeche", "t": "prisma_oberflaeche", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Pralinenkarton hat die Form eines geraden Prismas mit einem Quadrat als Grundfläche. Die Grundkante ist 6 cm lang. Die ganze Oberfläche des Kartons ist 192 cm² groß. Wie hoch ist der Karton?"}, "o": {"wert": 5, "einheit": "cm"}, "h": "Ziehe von der Oberfläche zuerst die beiden Grundflächen ab. Der Rest ist der Mantel, ein Rechteck mit Umfang mal Höhe.", "w": "Zwei Quadrate: 2 · 36 = 72 cm². Mantel: 192 − 72 = 120 cm². Der Umfang der Grundfläche ist 4 · 6 = 24 cm. Also ist die Höhe 120 : 24 = 5 cm. Probe: 72 + 24 · 5 = 192.", "form": "anwenden", "zaehlt": "ja", "r": 14417}, {"l": "prisma_umstellen", "t": "prisma_umstellen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Sandkasten hat eine rechteckige Grundfläche von 4 m². Es sind 1,6 m³ Sand eingefüllt, und der Sand liegt überall gleich hoch. Wie hoch liegt der Sand in Zentimetern?"}, "o": {"wert": 40, "einheit": "cm"}, "h": "Die Höhe ist das Volumen geteilt durch die Grundfläche. Am Ende musst du in Zentimeter umrechnen.", "w": "h = V : G = 1,6 m³ : 4 m² = 0,4 m = 40 cm. Probe: 4 m² · 0,4 m = 1,6 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14418}, {"l": "prisma_umstellen", "t": "prisma_umstellen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Becken hat die Form eines Prismas. Seine Grundfläche ist ein Trapez mit den parallelen Seiten 40 cm und 60 cm und dem Abstand 25 cm. In das Becken passen genau 25 Liter. Wie hoch ist das Prisma in Zentimetern?"}, "o": {"wert": 20, "einheit": "cm"}, "h": "Berechne zuerst die Trapezfläche. Rechne die Liter in cm³ um: 1 Liter = 1 000 cm³.", "w": "Grundfläche: (40 + 60) : 2 · 25 = 1 250 cm². Volumen: 25 l = 25 000 cm³. Höhe: 25 000 : 1 250 = 20 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14419}, {"l": "prisma_umstellen", "t": "prisma_umstellen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "In einem Quader-Gefäß mit der Grundfläche 20 cm mal 15 cm steht Saft 12 cm hoch. Der ganze Saft wird in ein Dreiecksprisma-Gefäß gegossen, das 40 cm hoch ist. Seine Grundfläche ist ein Dreieck mit der Grundseite 24 cm und der Höhe 10 cm. Wie hoch steht der Saft im zweiten Gefäß in Zentimetern?"}, "o": {"wert": 30, "einheit": "cm"}, "h": "Das Volumen des Safts bleibt beim Umgießen gleich. Berechne die Grundfläche des zweiten Gefäßes.", "w": "Volumen: 20 · 15 · 12 = 3 600 cm³. Grundfläche des Dreiecks: 24 · 10 : 2 = 120 cm². Füllhöhe: 3 600 : 120 = 30 cm. Das ist weniger als die Gefäßhöhe 40 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14420}, {"l": "zylinder_volumen", "t": "zylinder_volumen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Baumstamm hat die Form eines Zylinders mit dem Durchmesser 40 cm und der Länge 3 m. Wie viele Kubikdezimeter Holz sind das? Rechne mit π ≈ 3,14."}, "o": {"wert": 376.8, "einheit": "dm³"}, "h": "Rechne alle Maße in dm um. Aus dem Durchmesser bekommst du den Radius.", "w": "r = 40 cm : 2 = 20 cm = 2 dm, Länge = 3 m = 30 dm. V = π · r² · h ≈ 3,14 · 4 · 30 = 376,8 dm³.", "form": "anwenden", "zaehlt": "ja", "r": 14421}, {"l": "zylinder_volumen", "t": "zylinder_volumen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Betonrohr ist 2 m lang. Der äußere Radius ist 30 cm, der innere Radius ist 20 cm. Wie viele Kubikdezimeter Beton enthält das Rohr? Rechne mit π ≈ 3,14."}, "o": {"wert": 314, "einheit": "dm³"}, "h": "Das Rohr ist ein großer Zylinder, aus dem ein kleiner Zylinder herausgeschnitten ist. Rechne in dm.", "w": "Rechne in dm: R = 3 dm, r = 2 dm, Länge 20 dm. V = (π · R² − π · r²) · h = 3,14 · (9 − 4) · 20 = 3,14 · 100 = 314 dm³.", "form": "anwenden", "zaehlt": "ja", "r": 14422}, {"l": "zylinder_volumen", "t": "zylinder_volumen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Zylinder A hat den Radius 10 cm. Er ist 30 cm hoch mit Wasser gefüllt. Das ganze Wasser wird in einen Zylinder B mit dem Radius 5 cm gegossen. B ist hoch genug. Wie hoch steht das Wasser in B in Zentimetern?"}, "o": {"wert": 120, "einheit": "cm"}, "h": "Das Volumen bleibt gleich. Wie viel kleiner ist die Grundfläche von B als die von A? Denke an r².", "w": "Die Grundfläche ist π · r². A: π · 100, B: π · 25. B hat nur ein Viertel der Grundfläche von A. Bei gleichem Volumen steht das Wasser viermal so hoch: 4 · 30 = 120 cm. Probe: π · 100 · 30 = π · 25 · 120.", "form": "anwenden", "zaehlt": "ja", "r": 14423}, {"l": "zylinder_oberflaeche", "t": "zylinder_oberflaeche", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein zylinderförmiger Blecheimer ist oben offen. Er hat den Radius 15 cm und die Höhe 30 cm. Wie viele Quadratzentimeter Blech braucht man für Boden und Mantel? Rechne mit π ≈ 3,14."}, "o": {"wert": 3532.5, "einheit": "cm²"}, "h": "Der Eimer hat keinen Deckel. Der Mantel ist ein Rechteck: Kreisumfang mal Höhe.", "w": "Boden: π · r² ≈ 3,14 · 225 = 706,5 cm². Mantel: 2 · π · r · h ≈ 2 · 3,14 · 15 · 30 = 2 826 cm². Zusammen: 706,5 + 2 826 = 3 532,5 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14424}, {"l": "zylinder_oberflaeche", "t": "zylinder_oberflaeche", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Wassertank ist ein geschlossener Zylinder mit dem Durchmesser 1 m und der Höhe 2 m. Er wird außen zweimal gestrichen. Ein Liter Farbe reicht für einen Anstrich von 5 m². Wie viele Liter Farbe braucht man für die beiden Anstriche? Rechne mit π ≈ 3,14."}, "o": {"wert": 3.14, "einheit": "l"}, "h": "Berechne zuerst die ganze Oberfläche (Boden, Deckel, Mantel) in m². Der Radius ist die Hälfte des Durchmessers.", "w": "r = 0,5 m. Boden und Deckel: 2 · 3,14 · 0,25 = 1,57 m². Mantel: 2 · 3,14 · 0,5 · 2 = 6,28 m². Oberfläche: 7,85 m². Zwei Anstriche: 15,7 m². Farbe: 15,7 : 5 = 3,14 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 14425}, {"l": "zylinder_oberflaeche", "t": "zylinder_oberflaeche", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine geschlossene Blechdose hat die Form eines Zylinders mit dem Radius 4 cm. Für die ganze Dose (Boden, Deckel und Mantel) werden 326,56 cm² Blech gebraucht. Rechne mit π ≈ 3,14. Wie hoch ist die Dose in Zentimetern?"}, "o": {"wert": 9, "einheit": "cm"}, "h": "Ziehe zuerst Boden und Deckel ab. Der Rest ist der Mantel: Umfang mal Höhe.", "w": "Boden und Deckel: 2 · 3,14 · 16 = 100,48 cm². Mantel: 326,56 − 100,48 = 226,08 cm². Der Kreisumfang ist 2 · 3,14 · 4 = 25,12 cm. Höhe: 226,08 : 25,12 = 9 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14426}, {"l": "sach", "t": "sach", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein zylinderförmiger Wassertank hat den Durchmesser 2 m und ist 3 m hoch. Wie viele Liter fasst er? Rechne mit π ≈ 3,14. Es gilt 1 m³ = 1 000 Liter."}, "o": {"wert": 9420, "einheit": "l"}, "h": "Aus dem Durchmesser bekommst du den Radius. Rechne zuerst das Volumen in m³ aus.", "w": "r = 1 m. V = 3,14 · 1² · 3 = 9,42 m³. Das sind 9,42 · 1 000 = 9 420 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 14427}, {"l": "sach", "t": "sach", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Lagerhalle ist 20 m lang. Ihr Querschnitt besteht aus einem Rechteck (10 m breit, 4 m hoch) und einem Dreieck als Dach darüber (10 m breit, 3 m hoch). Wie groß ist der umbaute Raum der Halle in m³?"}, "o": {"wert": 1100, "einheit": "m³"}, "h": "Die Halle ist ein Prisma. Bestimme erst die Fläche des Querschnitts aus Rechteck und Dreieck.", "w": "Querschnitt: Rechteck 10 · 4 = 40 m², Dreieck 10 · 3 : 2 = 15 m². Zusammen 55 m². Volumen: 55 · 20 = 1 100 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14428}, {"l": "sach", "t": "sach", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein zylinderförmiger Behälter hat den Radius 20 cm. Ein quaderförmiger Behälter hat eine Grundfläche von 40 cm mal 30 cm. Beide sind 50 cm hoch mit Wasser gefüllt. Um wie viele Liter fasst der Zylinder mehr als der Quader? Rechne mit π ≈ 3,14. Es gilt 1 Liter = 1 000 cm³."}, "o": {"wert": 2.8, "einheit": "l"}, "h": "Berechne beide Volumina in cm³. Danach bildest du die Differenz und rechnest in Liter um.", "w": "Zylinder: 3,14 · 400 · 50 = 62 800 cm³ = 62,8 l. Quader: 40 · 30 · 50 = 60 000 cm³ = 60 l. Unterschied: 62,8 − 60 = 2,8 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 14429}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Becher A fasst 120 ml und ist ein Zylinder. Becher B ist genauso hoch, hat aber den doppelten Radius. Wie viele Milliliter fasst Becher B?"}, "o": {"wert": 480, "einheit": "ml"}, "h": "Die Höhe bleibt gleich. Wie ändert sich die Grundfläche π · r², wenn der Radius doppelt so groß wird?", "w": "Mit dem doppelten Radius wird r² viermal so groß, also auch die Grundfläche. Bei gleicher Höhe ist das Volumen viermal so groß: 4 · 120 = 480 ml.", "form": "anwenden", "zaehlt": "ja", "r": 14430}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Dose A ist ein Zylinder mit dem Radius 4 cm und der Höhe 6 cm. Dose B ist ein Zylinder mit dem Radius 6 cm und der Höhe 4 cm. Das Volumen von Dose B ist um n · π cm³ größer als das von Dose A. Welche Zahl ist n?"}, "o": {"wert": 48}, "h": "Berechne beide Volumina als Vielfache von π. Beachte, welche Größe quadriert wird.", "w": "A: π · 4² · 6 = 96π cm³. B: π · 6² · 4 = 144π cm³. Unterschied: 144π − 96π = 48π. Also ist n = 48. Die Dose mit dem größeren Radius ist größer, obwohl sie niedriger ist.", "form": "anwenden", "zaehlt": "ja", "r": 14431}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "begruenden", "y": "zahl", "f": {"text": "Ein Stapel aus 10 runden Pappscheiben steht gerade. Jede Scheibe hat den Radius 3 cm und ist 1 cm dick. Dann wird der Stapel seitlich verschoben, sodass er schief steht. Dabei ändert sich keine Scheibe. Wie groß ist das Volumen des schiefen Stapels in cm³? Rechne mit π ≈ 3,14."}, "o": {"wert": 282.6, "einheit": "cm³"}, "h": "Jede Scheibe hat dasselbe Volumen wie vorher. Wie viele Scheiben gibt es?", "w": "Das Volumen einer Scheibe ist 3,14 · 3² · 1 = 28,26 cm³. Beim Verschieben ändert sich keine Scheibe, also bleibt auch die Summe gleich: 10 · 28,26 = 282,6 cm³. Ein schiefer Zylinder hat dasselbe Volumen wie der gerade mit gleicher Grundfläche und Höhe.", "form": "anwenden", "zaehlt": "ja", "r": 14432}]$auf$::jsonb),
    (95, 'messen.volumen', 369, 21, $auf$[{"l": "einheitswuerfel", "t": "einheitswuerfel", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Schachtel ist innen 5 cm lang, 4 cm breit und 3 cm hoch. Kim füllt sie ganz mit Würfeln, die 1 cm Kante haben. Wie viele Würfel passen hinein?"}, "o": {"wert": 60}, "h": "Wie viele Würfel liegen in der untersten Schicht? Wie viele Schichten passen übereinander?", "w": "Eine Schicht hat 5 · 4 = 20 Würfel. Es passen 3 Schichten hinein: 20 · 3 = 60 Würfel.", "form": "anwenden", "zaehlt": "ja", "r": 14370}, {"l": "einheitswuerfel", "t": "einheitswuerfel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Quader ist aus Würfeln gebaut: 6 Würfel in der Länge, 3 in der Breite und 2 Schichten übereinander. Sam nimmt die oberste Schicht ganz weg. Wie viele Würfel bleiben liegen?"}, "o": {"wert": 18}, "h": "Wie viele Würfel hat eine Schicht? Wie viele Schichten bleiben übrig?", "w": "Eine Schicht hat 6 · 3 = 18 Würfel. Von 2 Schichten bleibt 1 Schicht. Es bleiben 18 Würfel liegen.", "form": "anwenden", "zaehlt": "ja", "r": 14371}, {"l": "einheitswuerfel", "t": "einheitswuerfel", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein großer Würfel besteht aus 5 · 5 · 5 kleinen Würfeln. Er wird außen ganz blau angemalt. Wie viele kleine Würfel haben dann keine blaue Fläche?"}, "o": {"wert": 27}, "h": "Welche kleinen Würfel liegen ganz innen? Wie viele Schichten sind es in jeder Richtung ohne die äußeren?", "w": "Außen liegen je 2 Schichten nicht innen: in jeder Richtung bleiben 5 − 2 = 3 Würfel. Innen liegt ein Würfel aus 3 · 3 · 3 = 27 kleinen Würfeln.", "form": "anwenden", "zaehlt": "ja", "r": 14372}, {"l": "quader", "t": "quader", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Umzugskarton ist 40 cm lang, 25 cm breit und 20 cm hoch. Wie groß ist sein Volumen?"}, "o": {"wert": 20000, "einheit": "cm³"}, "h": "Das Volumen eines Quaders ist Länge mal Breite mal Höhe.", "w": "Grundfläche: 40 · 25 = 1 000 cm². Volumen: 1 000 · 20 = 20 000 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14373}, {"l": "quader", "t": "quader", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Schwimmbecken ist 8 m lang und 4,5 m breit. Das Wasser steht 1,5 m hoch. Wie viel Kubikmeter Wasser sind im Becken?"}, "o": {"wert": 54, "einheit": "m³"}, "h": "Das Wasser bildet einen Quader. Seine Höhe ist die Wasserhöhe.", "w": "Grundfläche: 8 · 4,5 = 36 m². Volumen: 36 · 1,5 = 54 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14374}, {"l": "quader", "t": "quader", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Würfel mit 8 cm Kante und ein Quader mit 16 cm Länge und 8 cm Breite haben genau dasselbe Volumen. Wie hoch ist der Quader?"}, "o": {"wert": 4, "einheit": "cm"}, "h": "Berechne zuerst das Volumen des Würfels. Dann fehlt beim Quader nur die Höhe.", "w": "Würfel: 8 · 8 · 8 = 512 cm³. Die Grundfläche des Quaders ist 16 · 8 = 128 cm². Höhe: 512 : 128 = 4 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14375}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Regenwassertank fasst 3,6 m³. Wie viele Kubikdezimeter sind das?"}, "o": {"wert": 3600, "einheit": "dm³"}, "h": "Bei Volumen ist jeder Schritt zur nächsten Einheit mal oder durch 1 000. Von m³ nach dm³ ist es ein Schritt.", "w": "1 m³ = 1 000 dm³. Also 3,6 m³ = 3,6 · 1 000 = 3 600 dm³.", "form": "anwenden", "zaehlt": "ja", "r": 14376}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Sam hat 0,8 m³ Sand. Eine Schubkarre fasst 40 dm³. Wie viele volle Schubkarren ergibt der Sand?"}, "o": {"wert": 20}, "h": "Rechne zuerst die Kubikmeter in Kubikdezimeter um. Dann teilst du.", "w": "0,8 m³ = 800 dm³. Dann 800 : 40 = 20 Schubkarren.", "form": "anwenden", "zaehlt": "ja", "r": 14377}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Um wie viele Kubikzentimeter unterscheiden sich 2,5 dm³ und 2 400 cm³?"}, "o": {"wert": 100, "einheit": "cm³"}, "h": "Schreibe beide Angaben in derselben Einheit. Erst dann kannst du vergleichen.", "w": "2,5 dm³ = 2 500 cm³. Der Unterschied ist 2 500 − 2 400 = 100 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14378}, {"l": "liter", "t": "liter", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Regentonne ist innen 50 cm lang, 40 cm breit und 60 cm hoch. Wie viele Liter passen hinein, wenn sie ganz voll ist?"}, "o": {"wert": 120, "einheit": "l"}, "h": "Berechne das Volumen in cm³. Ein Liter sind 1 000 cm³.", "w": "Volumen: 50 · 40 · 60 = 120 000 cm³. Mit 1 l = 1 000 cm³ sind das 120 000 : 1 000 = 120 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 14379}, {"l": "liter", "t": "liter", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim füllt 6 Liter Saft aus einem Kanister in Becher. In jeden Becher kommen 250 ml. Wie viele Becher werden voll?"}, "o": {"wert": 24}, "h": "Rechne die Liter in Milliliter um. Dann teilst du.", "w": "6 l = 6 000 ml. 6 000 : 250 = 24 Becher.", "form": "anwenden", "zaehlt": "ja", "r": 14380}, {"l": "liter", "t": "liter", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Becken ist 3 m lang, 2 m breit und 1,2 m hoch. Es ist leer. Pro Minute fließen 40 Liter hinein. Nach wie vielen Minuten steht das Wasser 0,5 m hoch?"}, "o": {"wert": 75, "einheit": "Minuten"}, "h": "Wie viele Kubikmeter Wasser sind bei 0,5 m Höhe im Becken? Rechne in Liter um.", "w": "Bei 0,5 m Höhe sind es 3 · 2 · 0,5 = 3 m³ = 3 000 Liter. 3 000 : 40 = 75 Minuten.", "form": "anwenden", "zaehlt": "ja", "r": 14381}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quaderförmiger Karton fasst 3 600 cm³. Er ist 20 cm lang und 15 cm breit. Wie hoch ist er?"}, "o": {"wert": 12, "einheit": "cm"}, "h": "Teile das Volumen durch die Grundfläche.", "w": "Grundfläche: 20 · 15 = 300 cm². Höhe: 3 600 : 300 = 12 cm. Probe: 300 · 12 = 3 600.", "form": "anwenden", "zaehlt": "ja", "r": 14382}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Sandkasten ist 2 m lang und 1,5 m breit. Hinein kommen 0,6 m³ Sand, glatt verteilt. Wie viele Zentimeter hoch liegt der Sand?"}, "o": {"wert": 20, "einheit": "cm"}, "h": "Teile das Volumen durch die Grundfläche. Das Ergebnis ist zuerst in Metern.", "w": "Grundfläche: 2 · 1,5 = 3 m². Höhe: 0,6 : 3 = 0,2 m = 20 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14383}, {"l": "rueckwaerts", "t": "rueckwaerts", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine quaderförmige Dose ist innen 12 cm lang und 5 cm breit. Sie soll genau 1,5 Liter fassen. Wie hoch muss sie innen sein?"}, "o": {"wert": 25, "einheit": "cm"}, "h": "1 Liter sind 1 000 cm³. Wie groß ist das Volumen in cm³? Dann teilst du durch die Grundfläche.", "w": "1,5 l = 1 500 cm³. Grundfläche: 12 · 5 = 60 cm². Höhe: 1 500 : 60 = 25 cm.", "form": "anwenden", "zaehlt": "ja", "r": 14384}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Sockel besteht aus zwei Teilen. Unten liegt ein Quader mit 3 dm Länge, 2 dm Breite und 1 dm Höhe. Obendrauf steht ein Würfel mit 2 dm Kante. Wie groß ist das Volumen des ganzen Sockels?"}, "o": {"wert": 14, "einheit": "dm³"}, "h": "Berechne das Volumen jedes Teils einzeln. Dann addierst du.", "w": "Quader: 3 · 2 · 1 = 6 dm³. Würfel: 2 · 2 · 2 = 8 dm³. Zusammen 6 + 8 = 14 dm³.", "form": "anwenden", "zaehlt": "ja", "r": 14385}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Holzquader ist 10 cm lang, 8 cm breit und 6 cm hoch. Durch die Mitte wird von oben nach unten ein Loch mit quadratischem Querschnitt gebohrt: 3 cm mal 3 cm, ganz durch. Wie groß ist das Volumen des Holzes, das übrig bleibt?"}, "o": {"wert": 426, "einheit": "cm³"}, "h": "Berechne das Volumen des ganzen Quaders und das des Lochs. Das Loch geht über die ganze Höhe.", "w": "Ganzer Quader: 10 · 8 · 6 = 480 cm³. Loch: 3 · 3 · 6 = 54 cm³. Rest: 480 − 54 = 426 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14386}, {"l": "zusammengesetzt", "t": "zusammengesetzt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein offener Betontrog hat außen die Maße 5 m Länge, 3 m Breite und 2 m Höhe. Innen ist er ausgehöhlt: 4 m lang, 2 m breit und 1,5 m tief. Wie viele Kubikmeter Beton stecken in dem Trog?"}, "o": {"wert": 18, "einheit": "m³"}, "h": "Der Trog ist ein großer Quader, aus dem der Hohlraum fehlt. Berechne beide Volumen.", "w": "Außen: 5 · 3 · 2 = 30 m³. Hohlraum: 4 · 2 · 1,5 = 12 m³. Beton: 30 − 12 = 18 m³.", "form": "anwenden", "zaehlt": "ja", "r": 14387}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Schrank ist 1,9 m hoch, 0,6 m breit und 0,5 m tief. Zum Überschlag rundet Kim auf 2 m, 0,5 m und 0,5 m. Wie viele Kubikmeter ergibt der Überschlag?"}, "o": {"wert": 0.5, "einheit": "m³"}, "h": "Beim Überschlag rechnest du mit den gerundeten Kanten: Länge mal Breite mal Höhe.", "w": "Mit den gerundeten Werten: 2 · 0,5 · 0,5 = 0,5 m³. Das genaue Volumen (0,57 m³) liegt nahe dabei.", "form": "anwenden", "zaehlt": "ja", "r": 14388}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Quader hat das Volumen 20 cm³. Seine Länge und seine Breite werden jeweils verdoppelt. Die Höhe bleibt gleich. Wie groß ist jetzt das Volumen?"}, "o": {"wert": 80, "einheit": "cm³"}, "h": "Wie oft passt der alte Quader in den neuen? Die Länge wird doppelt so groß und die Breite auch.", "w": "Der Faktor 2 wirkt zweimal: 2 · 2 = 4. Das neue Volumen ist 20 · 4 = 80 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14389}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Ein Quader ist 2 cm lang, 3 cm breit und 4 cm hoch. Kim sagt: „Halbiere ich alle drei Kanten, wird auch das Volumen halbiert.“ Kim rechnet deshalb mit 12 cm³. Um wie viele Kubikzentimeter ist Kims Wert zu groß?"}, "o": {"wert": 9, "einheit": "cm³"}, "h": "Das Volumen des Quaders ist 24 cm³. Halbierst du jede der drei Kanten, wirkt der Faktor ein halbes dreimal.", "w": "Der Faktor 1/2 wirkt dreimal: 24 · 1/8 = 3 cm³. Kims Wert 12 cm³ ist 12 − 3 = 9 cm³ zu groß.", "form": "anwenden", "zaehlt": "ja", "r": 14390}]$auf$::jsonb),
    (112, 'terme.potenzgesetze_ganzzahlig', 112, 15, $auf$[{"l": "warum_gilt", "t": "warum_gilt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Die Menge eines Wirkstoffs im Blut halbiert sich jede Stunde. Zu Beginn sind es 160 mg. Nach n Stunden sind es 160 · 2⁻ⁿ mg. Wie viel Milligramm sind es nach 5 Stunden?"}, "o": {"wert": 5, "einheit": "mg"}, "h": "2⁻ⁿ bedeutet: n-mal halbieren. Schreibe 2⁻⁵ als Bruch.", "w": "2⁻⁵ ist der Bruch 1/2⁵ = 1/32. Also sind es nach 5 Stunden 160 · 1/32 = 160 : 32 = 5 mg. Probe: 160, 80, 40, 20, 10, 5 – fünfmal halbiert.", "form": "anwenden", "zaehlt": "ja", "r": 14113}, {"l": "warum_gilt", "t": "warum_gilt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim schneidet von einem 1 m langen Seil zuerst die Hälfte ab. Vom Rest schneidet Kim wieder die Hälfte ab, und danach noch einmal die Hälfte vom neuen Rest. Die drei abgeschnittenen Stücke sind 2⁻¹ m, 2⁻² m und 2⁻³ m lang. Wie viele Meter sind die drei Stücke zusammen lang? Gib das Ergebnis als Dezimalzahl an."}, "o": {"wert": 0.875, "einheit": "m"}, "h": "Schreibe jedes Stück als Bruch. Was bedeutet 2⁻³?", "w": "2⁻¹ = 1/2, 2⁻² = 1/4, 2⁻³ = 1/8. Zusammen: 1/2 + 1/4 + 1/8 = 4/8 + 2/8 + 1/8 = 7/8 = 0,875 m. Probe: Das Seil hat noch 1/8 m übrig, und 1 − 1/8 = 7/8.", "form": "anwenden", "zaehlt": "ja", "r": 14114}, {"l": "warum_gilt", "t": "warum_gilt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Substanz zerfällt so, dass ihre Menge jede Stunde auf die Hälfte sinkt. Jetzt sind 3 g da. Die Formel M(t) = 3 · 2⁻ᵗ gibt die Menge in Gramm t Stunden nach jetzt an. Für t = −2 liefert die Formel die Menge von vor 2 Stunden. Wie viel Gramm waren es vor 2 Stunden?"}, "o": {"wert": 12, "einheit": "g"}, "h": "Setze t = −2 ein. Was bedeutet 2 hoch (−(−2))? Was passiert mit der Menge, wenn man zwei Stunden zurückgeht?", "w": "Für t = −2 ist 2⁻ᵗ = 2²= 4. Also M(−2) = 3 · 4 = 12 g. Das passt: Von vor 2 Stunden bis jetzt wurde die Menge zweimal halbiert, 12 → 6 → 3.", "form": "anwenden", "zaehlt": "ja", "r": 14115}, {"l": "gleiche_basis_ganz", "t": "gleiche_basis_ganz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Staubkorn ist 10⁻⁵ m dick. Ein Blatt Papier ist 10⁻⁴ m dick. 50 Blätter liegen aufeinander. Wie viele Staubkörner müsste man aufeinanderlegen, um dieselbe Dicke zu erreichen?"}, "o": {"wert": 500, "einheit": "Staubkörner"}, "h": "Wie viele Staubkörner sind so dick wie ein Blatt? Teile 10⁻⁴ durch 10⁻⁵.", "w": "Ein Blatt: 10⁻⁴ : 10⁻⁵ = 10⁻⁴⁻⁽⁻⁵⁾ = 10¹ = 10 Staubkörner. Bei 50 Blättern sind es 50 · 10 = 500 Staubkörner.", "form": "anwenden", "zaehlt": "ja", "r": 14116}, {"l": "gleiche_basis_ganz", "t": "gleiche_basis_ganz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Transistor auf einem Chip ist 5 · 10⁻⁹ m breit. Ein Streifen auf dem Chip ist 2 · 10⁻⁵ m lang. Auf dem Streifen sollen Transistoren lückenlos nebeneinander liegen. Wie viele Transistoren passen auf den Streifen?"}, "o": {"wert": 4000, "einheit": "Transistoren"}, "h": "Teile die Länge des Streifens durch die Breite eines Transistors. Rechne Zahlen und Zehnerpotenzen getrennt.", "w": "Anzahl = (2 · 10⁻⁵) : (5 · 10⁻⁹) = (2 : 5) · 10⁻⁵⁻⁽⁻⁹⁾ = 0,4 · 10⁴ = 4 000. Es passen 4 000 Transistoren.", "form": "anwenden", "zaehlt": "ja", "r": 14117}, {"l": "gleiche_basis_ganz", "t": "gleiche_basis_ganz", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Kristall wiegt 10⁻³ g. Ein Päckchen enthält 10ᵏ solche Kristalle und wiegt zusammen 10² g. Welche ganze Zahl ist k?"}, "o": {"wert": 5}, "h": "Gesamtgewicht = Gewicht eines Kristalls mal Anzahl. Die Hochzahlen der Zehnerpotenzen werden dabei addiert.", "w": "Es gilt 10⁻³ · 10ᵏ = 10², also 10⁻³⁺ᵏ = 10². Daraus folgt −3 + k = 2 und k = 5. Probe: 10⁻³ · 10⁵ = 10² = 100 g.", "form": "anwenden", "zaehlt": "ja", "r": 14118}, {"l": "exponent_und_potenz", "t": "exponent_und_potenz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratisches Pixel auf einem Bildschirm hat die Seitenlänge 2⁻³ mm. Wie groß ist die Fläche des Pixels in mm²? Gib sie als Dezimalzahl an."}, "o": {"wert": 0.015625, "einheit": "mm²"}, "h": "Fläche eines Quadrats = Seite mal Seite. Welche Hochzahl hat (2⁻³)²?", "w": "A = (2⁻³)² = 2⁻³˙² = 2⁻⁶ = 1/64 = 0,015625 mm². Probe: 1/8 · 1/8 = 1/64.", "form": "anwenden", "zaehlt": "ja", "r": 14119}, {"l": "exponent_und_potenz", "t": "exponent_und_potenz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein würfelförmiger Behälter hat die Kantenlänge 5⁻¹ m. Wie viele Liter fasst er? Es gilt 1 m³ = 1 000 Liter."}, "o": {"wert": 8, "einheit": "l"}, "h": "Das Volumen eines Würfels ist Kante mal Kante mal Kante. Rechne zuerst in m³, dann in Liter.", "w": "V = (5⁻¹)³ m³ = 5⁻³ m³ = 1/125 m³. Das sind 1 000 : 125 = 8 Liter. Probe: Die Kante ist 0,2 m = 2 dm, und 2 dm · 2 dm · 2 dm = 8 dm³ = 8 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 14120}, {"l": "exponent_und_potenz", "t": "exponent_und_potenz", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Alex hat ein Zahlenrätsel gestellt: Es gibt genau eine ganze Zahl k, für die (3⁻²)ᵏ · 3⁷ = 3 gilt. Welche Zahl ist k?"}, "o": {"wert": 3}, "h": "Fasse die linke Seite zu einer einzigen Potenz von 3 zusammen. Welche Hochzahl hat (3⁻²)ᵏ?", "w": "(3⁻²)ᵏ = 3⁻²ᵏ. Dann ist 3⁻²ᵏ · 3⁷ = 3⁻²ᵏ⁺⁷. Das soll 3¹ sein, also −2k + 7 = 1, 2k = 6 und k = 3. Probe: (3⁻²)³ · 3⁷ = 3⁻⁶ · 3⁷ = 3.", "form": "anwenden", "zaehlt": "ja", "r": 14121}, {"l": "terme_vereinfachen", "t": "terme_vereinfachen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Rechteck hat den Flächeninhalt 6x⁴ cm². Eine Seite ist 2x⁶ cm lang. Dabei ist x = 2. Wie lang ist die andere Seite in Zentimetern?"}, "o": {"wert": 0.75, "einheit": "cm"}, "h": "Länge der anderen Seite = Fläche : bekannte Seite. Vereinfache den Bruch zuerst, setze x = 2 zuletzt ein.", "w": "Andere Seite = 6x⁴ : (2x⁶) = 3 · x⁴⁻⁶ = 3x⁻² = 3/x². Für x = 2: 3/4 = 0,75 cm. Probe: 2 · 2⁶ = 128 cm mal 0,75 cm = 96 cm², und 6 · 2⁴ = 96.", "form": "anwenden", "zaehlt": "ja", "r": 14122}, {"l": "terme_vereinfachen", "t": "terme_vereinfachen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Preis für ein Bastelset (in Euro) wird durch K(x) = 20x⁵ : (4x⁷) beschrieben. Dabei ist x die Zahl der gekauften Hunderterpackungen. Wie viel Euro kostet ein Set bei x = 5?"}, "o": {"wert": 0.2, "einheit": "€"}, "h": "Vereinfache K(x) zuerst: Zahlen für sich, Potenzen von x für sich. Danach setzt du x = 5 ein.", "w": "K(x) = (20 : 4) · x⁵⁻⁷ = 5x⁻² = 5/x². Für x = 5: 5/25 = 0,2. Ein Set kostet 0,20 €.", "form": "anwenden", "zaehlt": "ja", "r": 14123}, {"l": "terme_vereinfachen", "t": "terme_vereinfachen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Alex vereinfacht den Term (6x⁻³ · x⁵) : (3x⁻¹) zu einem Produkt c · xⁿ. Danach setzt er x = 2 ein. Welchen Wert erhält er?"}, "o": {"wert": 16}, "h": "Fasse Zähler und Nenner getrennt zusammen. Beim Teilen durch x⁻¹ wird die Hochzahl −1 abgezogen.", "w": "Zähler: 6x⁻³ · x⁵ = 6x². Dann 6x² : (3x⁻¹) = 2 · x²⁻⁽⁻¹⁾ = 2x³. Für x = 2: 2 · 8 = 16. Probe mit dem Ausgangsterm: 6 · 2⁻³ · 2⁵ = 24 und 3 · 2⁻¹ = 1,5, und 24 : 1,5 = 16.", "form": "anwenden", "zaehlt": "ja", "r": 14124}, {"l": "fehler_ganz", "t": "fehler_ganz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim behauptet: 4⁻¹ + 4⁻¹ = 4⁻². Mit einer Zahlenprobe kann man das prüfen. Um wie viel ist die linke Seite größer als die rechte Seite? Gib das Ergebnis als Dezimalzahl an."}, "o": {"wert": 0.4375}, "h": "Berechne beide Seiten einzeln als Bruch oder als Dezimalzahl. Dann bildest du die Differenz.", "w": "Linke Seite: 4⁻¹ + 4⁻¹ = 1/4 + 1/4 = 1/2 = 0,5. Rechte Seite: 4⁻² = 1/16 = 0,0625. Die Behauptung stimmt nicht. Unterschied: 0,5 − 0,0625 = 0,4375. Beim Addieren gleicher Potenzen werden die Hochzahlen nicht addiert.", "form": "anwenden", "zaehlt": "ja", "r": 14125}, {"l": "fehler_ganz", "t": "fehler_ganz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim berechnet 10⁻² · 10⁵ : 10⁻¹ und erhält 100. Die Zahlenprobe zeigt: Das stimmt nicht. Wie groß ist der richtige Wert?"}, "o": {"wert": 10000}, "h": "Kim hat beim Teilen durch 10⁻¹ vermutlich die Hochzahl falsch abgezogen. Rechne mit Brüchen nach.", "w": "Beim Malnehmen addiert man: −2 + 5 = 3, also 10³. Beim Teilen durch 10⁻¹ zieht man −1 ab: 3 − (−1) = 4, also 10⁴ = 10 000. Probe mit Zahlen: 0,01 · 100 000 = 1 000, und 1 000 : 0,1 = 10 000.", "form": "anwenden", "zaehlt": "ja", "r": 14126}, {"l": "fehler_ganz", "t": "fehler_ganz", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Kim behauptet für a ≠ 0: (a⁻²)³ · a⁵ = a. Wie groß ist die linke Seite für a = 2, wenn man richtig rechnet?"}, "o": {"wert": 0.5}, "h": "Berechne zuerst (a⁻²)³ mit der Regel für Potenz einer Potenz. Danach multiplizierst du mit a⁵.", "w": "(a⁻²)³ = a⁻⁶. Dann a⁻⁶ · a⁵ = a⁻¹ = 1/a. Für a = 2 ist das 1/2 = 0,5. Kims Rechnung bricht bei −6 + 5 ab, das ist −1 und nicht 1. Probe: 2⁻⁶ · 2⁵ = 32/64 = 0,5.", "form": "anwenden", "zaehlt": "ja", "r": 14127}]$auf$::jsonb),
    (304, 'groessen.proportional_teil2', 573, 9, $auf$[{"l": "erkennen", "t": "begriff", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Aufzug fährt gleichmäßig schnell. In 4 Sekunden fährt er 10 m. Die Zuordnung Zeit → Strecke ist proportional. Wie viele Meter fährt er in 10 Sekunden?"}, "o": {"wert": 25, "einheit": "m"}, "h": "Proportional heißt: Zur doppelten Zeit gehört die doppelte Strecke. Wie weit fährt der Aufzug in 1 Sekunde?", "w": "In 1 Sekunde fährt er 10 : 4 = 2,5 m. In 10 Sekunden fährt er 10 · 2,5 = 25 m. Probe: In 8 Sekunden wären es 20 m, dazu noch 2 Sekunden mit 5 m.", "form": "anwenden", "zaehlt": "ja", "r": 14574}, {"l": "erkennen", "t": "begriff", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Bäckerei A: 6 Brötchen kosten 2,40 €, jedes Brötchen kostet gleich viel. Bäckerei B: 1 € Tütengebühr und dazu 0,30 € für jedes Brötchen. Bei einer der beiden Bäckereien ist die Zuordnung Anzahl → Preis proportional. Wie viel Euro kosten dort 12 Brötchen?"}, "o": {"wert": 4.8, "einheit": "€"}, "h": "Bei einer proportionalen Zuordnung gehört zu 0 Brötchen der Preis 0. Bei welcher Bäckerei ist das so?", "w": "Bei Bäckerei B kostet schon die Tüte 1 €, auch bei 0 Brötchen: Das ist nicht proportional. Bei Bäckerei A kostet ein Brötchen 2,40 : 6 = 0,40 €. 12 Brötchen kosten 12 · 0,40 = 4,80 €. Das ist das Doppelte von 2,40 €.", "form": "anwenden", "zaehlt": "ja", "r": 14575}, {"l": "erkennen", "t": "begriff", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Sam behauptet: „Die Zuordnung Alter → Körpergröße ist proportional. Mit 8 Jahren war ich 128 cm groß, mit 12 Jahren bin ich also 192 cm groß.“ Mit 12 Jahren ist Sam aber 152 cm groß. Um wie viele Zentimeter weicht der Wert, den die Proportionalität liefert, vom wirklichen Wert ab?"}, "o": {"wert": 40, "einheit": "cm"}, "h": "Berechne zuerst, welche Größe bei Proportionalität für 12 Jahre herauskäme. Vergleiche mit 152 cm.", "w": "Bei Proportionalität wären es 128 : 8 = 16 cm je Jahr und mit 12 Jahren 16 · 12 = 192 cm. Wirklich sind es 152 cm. Abweichung: 192 − 152 = 40 cm. Das Wachstum ist nicht proportional (zu 0 Jahren gehört nicht 0 cm).", "form": "anwenden", "zaehlt": "ja", "r": 14576}, {"l": "vervielfachen", "t": "tabelle", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Auto verbraucht auf 100 km genau 6 Liter Benzin. Der Verbrauch ist auf jedem Kilometer gleich. Wie viele Liter Benzin verbraucht es auf 350 km?"}, "o": {"wert": 21, "einheit": "l"}, "h": "Wie viele Liter sind es auf 50 km? Zerlege 350 km in 300 km und 50 km.", "w": "300 km sind 3 · 100 km: 3 · 6 = 18 Liter. 50 km sind die Hälfte von 100 km: 3 Liter. Zusammen 18 + 3 = 21 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 14577}, {"l": "vervielfachen", "t": "tabelle", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Wasserhahn füllt gleichmäßig 18 Liter in 4 Minuten. Wie viele Minuten braucht er, um 63 Liter einzufüllen?"}, "o": {"wert": 14, "einheit": "Minuten"}, "h": "Wie viele Liter fließen in 1 Minute? Wie oft passt das in 63 Liter? Oder: Wie viele Liter sind es in 2 Minuten?", "w": "In 4 Minuten fließen 18 Liter, in 1 Minute 18 : 4 = 4,5 Liter. 63 : 4,5 = 14 Minuten. Probe: 14 · 4,5 = 63.", "form": "anwenden", "zaehlt": "ja", "r": 14578}, {"l": "vervielfachen", "t": "tabelle", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Rezept für 8 Personen braucht 600 g Mehl und 300 ml Milch. Zu Hause sind 1,5 kg Mehl und 600 ml Milch da. Für wie viele Personen reichen die Zutaten höchstens, wenn man nach dem Rezept kocht?"}, "o": {"wert": 16, "einheit": "Personen"}, "h": "Berechne getrennt, für wie viele Personen das Mehl und für wie viele die Milch reicht. Was begrenzt?", "w": "Mehl: 1 500 g : 600 g = 2,5 Rezepte, also 2,5 · 8 = 20 Personen. Milch: 600 ml : 300 ml = 2 Rezepte, also 2 · 8 = 16 Personen. Die Milch reicht nur für 16 Personen, sie begrenzt.", "form": "anwenden", "zaehlt": "ja", "r": 14579}, {"l": "pruefen", "t": "begriff", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim zahlt für 2 kg Birnen 5 €, für 3 kg Birnen 7,50 € und für 5 kg Birnen 12,50 €. Die Zuordnung Gewicht → Preis ist proportional. Wie viel Euro kosten 8 kg Birnen?"}, "o": {"wert": 20, "einheit": "€"}, "h": "Prüfe mit Preis : Gewicht in jeder Spalte, ob immer dieselbe Zahl herauskommt. Dann rechnest du weiter.", "w": "5 : 2 = 2,5; 7,5 : 3 = 2,5; 12,5 : 5 = 2,5. Immer 2,50 € je kg, die Tabelle ist proportional. 8 kg kosten 8 · 2,5 = 20 €. Probe: 3 kg + 5 kg: 7,50 + 12,50 = 20.", "form": "anwenden", "zaehlt": "ja", "r": 14580}, {"l": "pruefen", "t": "begriff", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Alle Paare einer Tabelle gehören zu einer proportionalen Zuordnung, nur ein Wert wurde falsch eingetragen: (3 | 12), (5 | 20), (8 | 34). Welche Zahl müsste statt 34 stehen?"}, "o": {"wert": 32}, "h": "Rechne in jeder Spalte zweite Zahl : erste Zahl. Welche Zahl kommt zweimal heraus?", "w": "12 : 3 = 4 und 20 : 5 = 4. Der Faktor ist 4. Bei 8 müsste 4 · 8 = 32 stehen, nicht 34. Probe: 34 : 8 = 4,25, das passt nicht zu 4.", "form": "anwenden", "zaehlt": "ja", "r": 14581}, {"l": "pruefen", "t": "begriff", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Eine Tabelle zeigt, wie viel Benzin ein Moped auf verschiedenen Strecken verbraucht: 15 km → 1,2 l; 24 km → 1,92 l; 33 km → 2,64 l. Die Zuordnung ist proportional. Wie viel Liter verbraucht das Moped auf 250 km?"}, "o": {"wert": 20, "einheit": "l"}, "h": "Prüfe, ob in jeder Spalte Liter : Kilometer dieselbe Zahl ergibt. Dann rechnest du den Verbrauch für 250 km.", "w": "1,2 : 15 = 0,08; 1,92 : 24 = 0,08; 2,64 : 33 = 0,08. Es sind immer 0,08 l je km, die Zuordnung ist proportional. 250 km: 250 · 0,08 = 20 l.", "form": "anwenden", "zaehlt": "ja", "r": 14582}]$auf$::jsonb),
    (305, 'terme.umformen_teil2', 789, 12, $auf$[{"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Tisch ist (x + 5) dm lang und (x + 3) dm breit. Seine Fläche in dm² ist ausmultipliziert x² + a · x + 15. Wie groß ist die Zahl a?"}, "o": {"wert": 8}, "h": "Multipliziere jedes Glied der ersten Klammer mit jedem Glied der zweiten. Welche Produkte enthalten x?", "w": "(x + 5)(x + 3) = x · x + x · 3 + 5 · x + 5 · 3 = x² + 3x + 5x + 15 = x² + 8x + 15. Also ist a = 8.", "form": "anwenden", "zaehlt": "ja", "r": 14790}, {"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Poster ist (x + 6) cm breit und (x − 2) cm hoch. Seine Fläche in cm² ist ausmultipliziert und zusammengefasst x² + p · x + q. Wie groß ist die Summe p + q?"}, "o": {"wert": -8}, "h": "Es entstehen vier Produkte. Achte beim Glied −2 auf das Vorzeichen. Fasse die Glieder mit x zusammen.", "w": "(x + 6)(x − 2) = x² − 2x + 6x − 12 = x² + 4x − 12. Also ist p = 4 und q = −12. Die Summe ist 4 + (−12) = −8.", "form": "anwenden", "zaehlt": "ja", "r": 14791}, {"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine rechteckige Terrasse hat die Seitenlängen (x + a) m und (x + b) m, dabei sind a und b ganze Zahlen mit 0 < a < b. Ihre Fläche ist x² + 9x + 14 m². Wie lang ist die längere Seite der Terrasse, wenn x = 10 ist?"}, "o": {"wert": 17, "einheit": "m"}, "h": "Beim Ausmultiplizieren entsteht x² + (a + b) · x + a · b. Welche zwei ganzen Zahlen haben die Summe 9 und das Produkt 14?", "w": "Es muss a + b = 9 und a · b = 14 gelten. Das passt zu a = 2 und b = 7. Die Seiten sind (x + 2) und (x + 7). Für x = 10: 12 m und 17 m. Die längere Seite ist 17 m lang. Probe: (x + 2)(x + 7) = x² + 9x + 14.", "form": "anwenden", "zaehlt": "ja", "r": 14792}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Wand hat die Fläche 15x + 20 m². Sie ist ein Rechteck, und eine Seite ist 5 m lang. Wie lang ist die andere Seite, wenn x = 4 ist?"}, "o": {"wert": 16, "einheit": "m"}, "h": "Klammere den größten gemeinsamen Faktor aus. Er steht für die Seite, die du schon kennst.", "w": "15x + 20 = 5 · (3x + 4). Die eine Seite ist 5 m lang, also ist die andere Seite 3x + 4. Für x = 4: 3 · 4 + 4 = 16 m. Probe: 5 · 16 = 80 und 15 · 4 + 20 = 80.", "form": "anwenden", "zaehlt": "ja", "r": 14793}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Gewinn eines Marktstands ist G = 4x² + 28x Euro, wobei x die Zahl der verkauften Kisten ist. Klammert man den größten gemeinsamen Faktor aus, erhält man G = c · x · (x + d). Wie groß ist die Summe c + d?"}, "o": {"wert": 11}, "h": "Welche Zahl und welche Potenz von x stecken in beiden Gliedern? Was bleibt in der Klammer?", "w": "Der größte gemeinsame Faktor von 4x² und 28x ist 4x. 4x² : 4x = x und 28x : 4x = 7. Also G = 4x · (x + 7), das heißt c = 4 und d = 7. Die Summe ist 11. Probe: 4x · x + 4x · 7 = 4x² + 28x.", "form": "anwenden", "zaehlt": "ja", "r": 14794}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Rechteck hat die Fläche 6x² + 9x (in cm²) und eine Seite der Länge 3x cm. Wie groß ist der Umfang des Rechtecks in cm, wenn x = 4 ist?"}, "o": {"wert": 46, "einheit": "cm"}, "h": "Die Fläche ist Länge mal Breite. Klammere 3x aus, dann erkennst du die andere Seite.", "w": "6x² + 9x = 3x · (2x + 3). Die eine Seite ist 3x, die andere 2x + 3. Für x = 4: 12 cm und 11 cm. Umfang = 2 · (12 + 11) = 46 cm. Probe: Fläche 12 · 11 = 132 = 6 · 16 + 9 · 4.", "form": "anwenden", "zaehlt": "ja", "r": 14795}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratischer Teppich hat die Seitenlänge (x + 3) m. Seine Fläche in m² ist ausmultipliziert x² + b · x + 9. Wie groß ist b?"}, "o": {"wert": 6}, "h": "Das Mittelglied bei (a + b)² ist 2 · a · b. Was ist hier a und was ist b?", "w": "(x + 3)² = x² + 2 · x · 3 + 3² = x² + 6x + 9. Also ist b = 6. Das Mittelglied darf man nie vergessen.", "form": "anwenden", "zaehlt": "ja", "r": 14796}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein rechteckiges Feld ist 52 m lang und 48 m breit. Wie groß ist seine Fläche in m²? Rechne geschickt mit (50 + 2) · (50 − 2)."}, "o": {"wert": 2496, "einheit": "m²"}, "h": "Die beiden Klammern unterscheiden sich nur im Vorzeichen. Welche binomische Formel passt?", "w": "(50 + 2)(50 − 2) = 50² − 2² = 2 500 − 4 = 2 496. Probe: 52 · 48 = 2 496.", "form": "anwenden", "zaehlt": "ja", "r": 14797}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein quadratisches Beet hat die Fläche 4x² + 20x + k (in m²) und die Seitenlänge 2x + m (in m). Dabei sind k und m feste Zahlen. Wie lang ist die Seite des Beets für x = 3?"}, "o": {"wert": 11, "einheit": "m"}, "h": "Vergleiche die Fläche mit (2x + m)². Welches Glied bei (2x + m)² enthält m und x?", "w": "(2x + m)² = 4x² + 4m · x + m². Der Vergleich mit 4x² + 20x + k gibt 4m = 20, also m = 5 (und k = 25). Die Seite ist 2x + 5. Für x = 3: 2 · 3 + 5 = 11 m. Probe: 11² = 121 = 4 · 9 + 20 · 3 + 25.", "form": "anwenden", "zaehlt": "ja", "r": 14798}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratisches Foto hat die Seitenlänge x cm. Ein Rahmen ist ringsum 2 cm breit, der Rahmen allein hat die Fläche 48 cm². Die Außenseite des Rahmens ist x + 4 cm lang. Wie lang ist die Seite des Fotos in cm?"}, "o": {"wert": 4, "einheit": "cm"}, "h": "Die Rahmenfläche ist das äußere Quadrat minus das Foto. Stelle die Gleichung (x + 4)² − x² = 48 auf.", "w": "(x + 4)² − x² = 48 → x² + 8x + 16 − x² = 48 → 8x + 16 = 48 → 8x = 32 → x = 4. Das Foto ist 4 cm lang. Probe: 8² − 4² = 64 − 16 = 48.", "form": "anwenden", "zaehlt": "ja", "r": 14799}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein quadratisches Feld hat die Seitenlänge x + 5 m, ein zweites quadratisches Feld hat die Seitenlänge x − 3 m. Das erste Feld ist 96 m² größer als das zweite. Wie groß ist x?"}, "o": {"wert": 5, "einheit": "m"}, "h": "Multipliziere beide Klammern mit den binomischen Formeln aus. Was passiert mit x²?", "w": "(x + 5)² − (x − 3)² = 96 → x² + 10x + 25 − (x² − 6x + 9) = 96 → 16x + 16 = 96 → 16x = 80 → x = 5. Die Felder sind 10 m und 2 m lang. Probe: 100 − 4 = 96.", "form": "anwenden", "zaehlt": "ja", "r": 14800}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein quadratisches Grundstück hat die Seitenlänge x + 3 m. Ein rechteckiges Grundstück ist x m breit und x + 7 m lang. Beide Grundstücke sind gleich groß. Wie lang ist die Seite des quadratischen Grundstücks in Metern?"}, "o": {"wert": 12, "einheit": "m"}, "h": "Stelle die Gleichung (x + 3)² = x · (x + 7) auf. Multipliziere beide Seiten aus.", "w": "(x + 3)² = x · (x + 7) → x² + 6x + 9 = x² + 7x → 9 = x. Also ist x = 9 und die Seite des Quadrats ist 9 + 3 = 12 m lang. Probe: 12² = 144 und 9 · 16 = 144.", "form": "anwenden", "zaehlt": "ja", "r": 14801}]$auf$::jsonb),
    (306, 'geometrie.konstruktion_teil2', 632, 6, $auf$[{"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Drachen aus Papier hat die Form eines Drachenvierecks ABCD. Die Symmetrieachse ist die Diagonale AC. Der Winkel bei A ist 70° und der Winkel bei C ist 50°. Wie groß ist der Winkel bei B?"}, "o": {"wert": 120, "einheit": "°"}, "h": "Welche beiden Winkel sind gleich groß? Alle vier Winkel zusammen ergeben 360°.", "w": "Die Winkel bei B und D sind gleich, weil die Figur symmetrisch zu AC ist. Alle vier Winkel ergeben 360°. Also ist 360° − 70° − 50° = 240° der Rest. Er verteilt sich auf zwei gleiche Winkel: 240° : 2 = 120°.", "form": "anwenden", "zaehlt": "ja", "r": 14633}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Fensterrahmen hat die Form eines Parallelogramms ABCD. Der Winkel bei A ist dreimal so groß wie der Winkel bei B. Wie groß ist der Winkel bei A?"}, "o": {"wert": 135, "einheit": "°"}, "h": "Welche Summe haben zwei benachbarte Winkel im Parallelogramm? Aus wie vielen gleichen Teilen besteht diese Summe?", "w": "Benachbarte Winkel im Parallelogramm ergeben zusammen 180°. Der Winkel bei A besteht aus 3 Teilen, der Winkel bei B aus 1 Teil, zusammen 4 Teile. Ein Teil ist 180° : 4 = 45°. Der Winkel bei A ist 3 · 45° = 135°. Probe: 135° + 45° = 180°.", "form": "anwenden", "zaehlt": "ja", "r": 14634}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "In einer Raute ABCD bildet die Diagonale AC mit der Seite AB einen Winkel von 28°. Sam baut die Raute aus vier gleich langen Holzstäben nach. Wie groß ist der Winkel bei B?"}, "o": {"wert": 124, "einheit": "°"}, "h": "Die Diagonale halbiert den Winkel bei A. Welcher Winkel ist ein Nachbar des Winkels bei A?", "w": "Die Diagonale AC halbiert den Winkel bei A, also ist der Winkel bei A gleich 2 · 28° = 56°. Benachbarte Winkel in der Raute ergeben zusammen 180°. Der Winkel bei B ist 180° − 56° = 124°.", "form": "anwenden", "zaehlt": "ja", "r": 14635}, {"l": "vierecke_konstruieren", "t": "vierecke_konstruieren", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Für ein Bastelprojekt sollst du ein Quadrat, eine Raute, ein Rechteck und ein Parallelogramm zeichnen. Du willst jede Figur mit so wenigen Angaben wie möglich festlegen. Wie viele Angaben brauchst du für alle vier Figuren zusammen?"}, "o": {"wert": 8}, "h": "Wie viele Bestimmungsstücke braucht jede der vier Figuren einzeln?", "w": "Ein Quadrat braucht 1 Stück (die Seite). Eine Raute braucht 2 Stücke, ein Rechteck 2 Stücke, ein Parallelogramm 3 Stücke. Zusammen: 1 + 2 + 2 + 3 = 8 Angaben.", "form": "anwenden", "zaehlt": "ja", "r": 14636}, {"l": "vierecke_konstruieren", "t": "vierecke_konstruieren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Gartenbeet hat die Form eines Drachenvierecks ABCD mit der Symmetrieachse AC. Beim Abstecken misst Noa den Winkel bei A mit 100° und den Winkel bei B mit 70°. Wie groß ist der Winkel bei C?"}, "o": {"wert": 120, "einheit": "°"}, "h": "Welche zwei Winkel sind gleich groß? Bedenke die Winkelsumme im Viereck.", "w": "Die Figur ist symmetrisch zu AC, also sind die Winkel bei B und D gleich: 70° und 70°. Alle vier Winkel ergeben 360°. Der Winkel bei C ist 360° − 100° − 70° − 70° = 120°.", "form": "anwenden", "zaehlt": "ja", "r": 14637}, {"l": "vierecke_konstruieren", "t": "vierecke_konstruieren", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Schild hat die Form eines Parallelogramms ABCD. Der stumpfe Winkel bei B ist um 36° kleiner als das Dreifache des spitzen Winkels bei A. Wie groß ist der stumpfe Winkel bei B?"}, "o": {"wert": 126, "einheit": "°"}, "h": "Benachbarte Winkel ergeben zusammen 180°. Schreibe den Winkel bei B mit dem Winkel bei A auf.", "w": "Es gilt α + β = 180° und β = 3α − 36°. Einsetzen: α + 3α − 36° = 180°, also 4α = 216° und α = 54°. Dann ist β = 180° − 54° = 126°. Probe: 3 · 54° − 36° = 126°.", "form": "anwenden", "zaehlt": "ja", "r": 14638}]$auf$::jsonb),
    (308, 'abbildungen.kongruenz_teil3', 751, 9, $auf$[{"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Auf einem Spielfeld mit Koordinaten liegt die Mitte bei Z(2 | 3). Eine Spielfigur steht auf P(5 | 7). Eine zweite Figur steht genau gegenüber, sodass Z die Mitte der Strecke zwischen den beiden Figuren ist. Welche y-Koordinate hat die zweite Figur?"}, "o": {"wert": -1}, "h": "Von P(5 | 7) nach Z(2 | 3) ändert sich die y-Koordinate um einen bestimmten Betrag. Gehe denselben Weg von Z aus noch einmal.", "w": "In y-Richtung geht man von P nach Z um 7 − 3 = 4 nach unten. Von Z aus noch einmal 4 nach unten: 3 − 4 = −1. Oder: y′ = 2 · 3 − 7 = −1. Die zweite Figur hat die y-Koordinate −1.", "form": "anwenden", "zaehlt": "ja", "r": 14752}, {"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Drohne fliegt in gerader Linie von R(−4 | 6) über eine Landeplatte bei S(2 | 3) hinweg und genau so weit dahinter weiter. S liegt also in der Mitte ihres Flugwegs. Wie groß ist die Summe der beiden Koordinaten ihres Zielpunkts?"}, "o": {"wert": 8}, "h": "Wie weit geht es von R nach S in x-Richtung und wie weit in y-Richtung? Gehe denselben Weg von S noch einmal.", "w": "Von R nach S: x ändert sich um 2 − (−4) = 6, y um 3 − 6 = −3. Von S noch einmal: x = 2 + 6 = 8, y = 3 − 3 = 0. Der Zielpunkt ist (8 | 0). Die Summe der Koordinaten ist 8 + 0 = 8.", "form": "anwenden", "zaehlt": "ja", "r": 14753}, {"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Zwei Antennen stehen punktsymmetrisch zu einem Sendemast Z: die eine bei P(4 | −3), die andere bei P′(−10 | 11). Z ist also die Mitte der Strecke PP′. Wie groß ist die Summe der beiden Koordinaten von Z?"}, "o": {"wert": 1}, "h": "Z liegt in der Mitte von P und P′. Bestimme erst die x-Koordinate, dann die y-Koordinate von Z.", "w": "Z ist die Mitte: x = (4 + (−10)) : 2 = −3 und y = (−3 + 11) : 2 = 4. Also Z(−3 | 4). Die Summe ist −3 + 4 = 1. Probe: Von P nach Z geht es 7 nach links und 7 nach oben, von Z nach P′ noch einmal 7 nach links und 7 nach oben.", "form": "anwenden", "zaehlt": "ja", "r": 14754}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Auf einem Spielbrett mit Koordinatensystem steht eine Figur auf P(4 | 1). Sie wird um den Ursprung O(0 | 0) um 90° gegen den Uhrzeigersinn gedreht. Dabei wird aus (x | y) der Punkt (−y | x). Welche x-Koordinate hat die Figur danach?"}, "o": {"wert": -1}, "h": "Setze x = 4 und y = 1 in die Regel (x | y) → (−y | x) ein. Welche Zahl steht an erster Stelle?", "w": "Aus (4 | 1) wird (−1 | 4). Die x-Koordinate ist −1 (das Gegenteil der alten y-Koordinate 1).", "form": "anwenden", "zaehlt": "ja", "r": 14755}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Ausleger eines Krans dreht sich um den Mast bei Z(3 | −2) um 90° gegen den Uhrzeigersinn. Seine Spitze steht zuerst bei P(7 | 1). Aus einem Vektor (a | b) wird bei dieser Drehung der Vektor (−b | a). Wie groß ist die Summe der beiden Koordinaten der Spitze nach der Drehung?"}, "o": {"wert": 2}, "h": "Rechne zuerst den Vektor von Z nach P. Drehe diesen Vektor. Trage ihn danach wieder bei Z an.", "w": "Vektor von Z nach P: (7 − 3 | 1 − (−2)) = (4 | 3). Gedreht: (−3 | 4). Von Z aus: (3 + (−3) | −2 + 4) = (0 | 2). Die Summe der Koordinaten ist 0 + 2 = 2.", "form": "anwenden", "zaehlt": "ja", "r": 14756}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Figur wurde um Z(2 | 1) um 90° gegen den Uhrzeigersinn gedreht. Dabei wird aus einem Vektor (a | b) der Vektor (−b | a). Nach der Drehung steht die Figur bei P′(−2 | 7). Wie groß ist die Summe der beiden Koordinaten des Punktes P, an dem sie vorher stand?"}, "o": {"wert": 13}, "h": "Rechne den Vektor von Z nach P′. Welcher Vektor (a | b) wird durch die Drehung zu diesem Vektor?", "w": "Vektor von Z nach P′: (−2 − 2 | 7 − 1) = (−4 | 6). Er ist das Bild von (a | b) mit −b = −4 und a = 6, also b = 4. Der ursprüngliche Vektor ist (6 | 4). Von Z aus: P = (2 + 6 | 1 + 4) = (8 | 5). Die Summe ist 13. Probe: (6 | 4) wird zu (−4 | 6).", "form": "anwenden", "zaehlt": "ja", "r": 14757}, {"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Drohne fliegt auf einer Karte (x zeigt nach Osten, y nach Norden) den Vektor (5 | 2). Dann dreht sie sich um 90° nach rechts, also im Uhrzeigersinn, und fliegt gleich weit. Dabei wird aus (x | y) der Vektor (y | −x). Welche y-Koordinate hat der zweite Flugvektor?"}, "o": {"wert": -5}, "h": "Setze x = 5 und y = 2 in die Regel (x | y) → (y | −x) ein. Welche Zahl steht an zweiter Stelle?", "w": "Aus (5 | 2) wird (2 | −5). Die zweite Koordinate ist −x = −5.", "form": "anwenden", "zaehlt": "ja", "r": 14758}, {"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Wanderer geht auf einer Karte von A(−2 | 3) nach B(4 | 5). Der Vektor AB wird um 90° gegen den Uhrzeigersinn gedreht (aus (x | y) wird (−y | x)) und bei B angesetzt. Er endet in C. Welche y-Koordinate hat C?"}, "o": {"wert": 11}, "h": "Berechne zuerst den Vektor AB. Drehe ihn, dann gehe vom Punkt B aus weiter.", "w": "AB = (4 − (−2) | 5 − 3) = (6 | 2). Gedreht: (−2 | 6). Von B(4 | 5) aus: C = (4 − 2 | 5 + 6) = (2 | 11). Die y-Koordinate ist 11.", "form": "anwenden", "zaehlt": "ja", "r": 14759}, {"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Vektor v wird nacheinander um +90°, um 180° und um −90° gedreht. Das Ergebnis ist der Vektor (−3 | 7). Dabei gilt: +90°: (x | y) → (−y | x); −90°: (x | y) → (y | −x); 180°: (x | y) → (−x | −y). Wie groß ist die Summe der beiden Koordinaten von v?"}, "o": {"wert": -4}, "h": "Wie viel wird insgesamt gedreht? Fasse die drei Drehungen zu einer zusammen.", "w": "Insgesamt wird um 90° + 180° − 90° = 180° gedreht. Eine Drehung um 180° macht aus v = (x | y) den Vektor (−x | −y) = (−3 | 7). Also ist v = (3 | −7). Die Summe ist 3 + (−7) = −4.", "form": "anwenden", "zaehlt": "ja", "r": 14760}]$auf$::jsonb),
    (310, 'raum.schraegbilder_teil2', 582, 12, $auf$[{"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Zimmer hat die Form eines Quaders. Die Ecke A liegt im Ursprung (0 | 0 | 0). Das Zimmer ist 6 m lang (x-Richtung), 3 m breit (y-Richtung) und 4 m hoch (z-Richtung). Die Ecke G liegt A genau gegenüber, an der Decke. Wie groß ist die Summe der drei Koordinaten von G?"}, "o": {"wert": 13}, "h": "Wie weit ist G von A entfernt, in x-, in y- und in z-Richtung?", "w": "G liegt 6 m in x-Richtung, 3 m in y-Richtung und 4 m in z-Richtung von A entfernt. Also G(6 | 3 | 4). Die Summe ist 6 + 3 + 4 = 13.", "form": "anwenden", "zaehlt": "ja", "r": 14583}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Quader ABCDEFGH hat die Ecken A(1 | 2 | 0), B(7 | 2 | 0), D(1 | 5 | 0) und E(1 | 2 | 4). Seine Kanten verlaufen parallel zu den Achsen. M ist der Mittelpunkt des ganzen Quaders. Wie groß ist die Summe der drei Koordinaten von M? Gib das Ergebnis als Dezimalzahl an."}, "o": {"wert": 9.5}, "h": "Der Mittelpunkt liegt in jeder Richtung genau in der Mitte zwischen der kleinsten und der größten Koordinate. Welche Ecke liegt A gegenüber?", "w": "Die Ecke G liegt A gegenüber: G(7 | 5 | 4). M ist die Mitte von A und G: x = (1 + 7) : 2 = 4, y = (2 + 5) : 2 = 3,5, z = (0 + 4) : 2 = 2. Also M(4 | 3,5 | 2). Die Summe ist 4 + 3,5 + 2 = 9,5.", "form": "anwenden", "zaehlt": "ja", "r": 14584}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Quader steht mit der Ecke A im Ursprung. Seine Kanten verlaufen parallel zu den Achsen. Die Ecke G, die A gegenüberliegt, hat die Koordinaten (8 | 6 | h). Das Volumen des Quaders ist 240 Volumeneinheiten. Wie groß ist h?"}, "o": {"wert": 5}, "h": "Die Koordinaten von G sind die Kantenlängen des Quaders. Das Volumen ist Länge mal Breite mal Höhe.", "w": "Die Kanten sind 8, 6 und h lang. Das Volumen ist 8 · 6 · h = 48h = 240. Also ist h = 240 : 48 = 5. Probe: 8 · 6 · 5 = 240.", "form": "anwenden", "zaehlt": "ja", "r": 14585}, {"l": "rotation", "t": "rotation", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Töpfer stellt sich vor, dass ein Rechteck mit den Seiten 4 cm und 9 cm um die 9-cm-Seite rotiert. Es entsteht ein Zylinder. Wie groß ist sein Volumen in cm³? Rechne mit π ≈ 3,14."}, "o": {"wert": 452.16, "einheit": "cm³"}, "h": "Welche Seite liegt auf der Drehachse? Die andere Seite wird zum Radius des Kreises.", "w": "Die 9-cm-Seite liegt auf der Achse und wird die Höhe, die 4-cm-Seite wird der Radius. V = π · r² · h ≈ 3,14 · 16 · 9 = 452,16 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14586}, {"l": "rotation", "t": "rotation", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Rechteck mit den Seiten 5 cm und 8 cm dreht sich einmal um die 8-cm-Seite und einmal um die 5-cm-Seite. So entstehen zwei verschiedene Zylinder. Um wie viele Kubikzentimeter ist der größere Zylinder größer als der kleinere? Rechne mit π ≈ 3,14."}, "o": {"wert": 376.8, "einheit": "cm³"}, "h": "Berechne beide Volumina. Beachte, welche Seite jeweils zum Radius und welche zur Höhe wird.", "w": "Um die 8-cm-Seite: r = 5 cm, h = 8 cm, V = 3,14 · 25 · 8 = 628 cm³. Um die 5-cm-Seite: r = 8 cm, h = 5 cm, V = 3,14 · 64 · 5 = 1 004,8 cm³. Unterschied: 1 004,8 − 628 = 376,8 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14587}, {"l": "rotation", "t": "rotation", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Rechteck dreht sich um eine Seite, die 8 cm lang ist. Der entstehende Zylinder hat das Volumen 226,08 cm³. Rechne mit π ≈ 3,14. Wie breit ist das Rechteck in Zentimetern?"}, "o": {"wert": 3, "einheit": "cm"}, "h": "Die gesuchte Breite wird beim Drehen zum Radius. Stelle die Volumenformel nach r² um.", "w": "Die 8-cm-Seite wird die Höhe, die gesuchte Breite wird der Radius r. Aus 3,14 · r² · 8 = 226,08 folgt r² = 226,08 : 25,12 = 9. Also ist r = 3 cm. Probe: 3,14 · 9 · 8 = 226,08.", "form": "anwenden", "zaehlt": "ja", "r": 14588}, {"l": "axialschnitt", "t": "axialschnitt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Eiswaffel hat die Form eines Kegels mit dem Radius 3 cm und der Höhe 12 cm. Sam schneidet sie der Länge nach genau durch die Achse. Wie groß ist die Fläche der Schnittfläche in cm²?"}, "o": {"wert": 36, "einheit": "cm²"}, "h": "Der Axialschnitt eines Kegels ist ein Dreieck. Wie lang ist seine Grundseite, und wie hoch ist es?", "w": "Der Axialschnitt ist ein gleichschenkliges Dreieck. Die Grundseite ist der Durchmesser 2 · 3 = 6 cm, die Höhe ist 12 cm. A = 6 · 12 : 2 = 36 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14589}, {"l": "axialschnitt", "t": "axialschnitt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Holzkugel wird genau durch ihren Mittelpunkt in zwei Hälften gesägt. Der Umfang der Schnittfläche ist 62,8 cm. Rechne mit π ≈ 3,14. Wie groß ist die Fläche der Schnittfläche in cm²?"}, "o": {"wert": 314, "einheit": "cm²"}, "h": "Die Schnittfläche ist ein Kreis mit dem Radius der Kugel. Berechne zuerst den Radius aus dem Umfang.", "w": "Der Schnitt ist ein Kreis mit dem Radius r der Kugel. Aus dem Umfang 2 · 3,14 · r = 62,8 folgt r = 62,8 : 6,28 = 10 cm. Die Fläche ist 3,14 · 10 · 10 = 314 cm².", "form": "anwenden", "zaehlt": "ja", "r": 14590}, {"l": "axialschnitt", "t": "axialschnitt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Der Axialschnitt eines Zylinders ist ein Quadrat mit dem Umfang 48 cm. Rechne mit π ≈ 3,14. Wie groß ist das Volumen des Zylinders in cm³?"}, "o": {"wert": 1356.48, "einheit": "cm³"}, "h": "Wie lang ist die Seite des Quadrats? Welche Seite des Quadrats ist der Durchmesser, welche die Höhe des Zylinders?", "w": "Die Seite des Quadrats ist 48 : 4 = 12 cm. Sie ist zugleich der Durchmesser und die Höhe. Also ist r = 6 cm und h = 12 cm. V = 3,14 · 36 · 12 = 1 356,48 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 14591}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Pralinenschachtel hat die Form eines Quaders. Ihre Grundfläche ist ein Quadrat, die Höhe ist aber nicht gleich der Länge der Grundseite. Wie viele Symmetrieebenen hat die Schachtel?"}, "o": {"wert": 5}, "h": "Zähle erst die Ebenen, die die Höhe enthalten (Symmetrieachsen des Quadrats). Dann die Ebene parallel zur Grundfläche.", "w": "Ebenen durch die Höhe: Sie entsprechen den 4 Symmetrieachsen des Quadrats (2 Mittellinien, 2 Diagonalen). Dazu kommt die Ebene in halber Höhe, parallel zur Grundfläche. Zusammen 4 + 1 = 5 Symmetrieebenen.", "form": "anwenden", "zaehlt": "ja", "r": 14592}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Spielzeughändler hat drei Körper: einen Würfel, eine gerade Pyramide mit quadratischer Grundfläche und ein gerades Prisma, dessen Grundfläche ein gleichseitiges Dreieck ist. Wie viele Symmetrieebenen haben die drei Körper zusammen?"}, "o": {"wert": 17, "einheit": "Ebenen"}, "h": "Der Würfel hat 9 Ebenen. Für Pyramide und Prisma zählst du erst die Symmetrieachsen der Grundfläche. Beim Prisma kommt noch eine Ebene dazu.", "w": "Würfel: 9 Ebenen. Gerade Pyramide über dem Quadrat: 4 Ebenen (eine je Symmetrieachse des Quadrats). Gerades Prisma über dem gleichseitigen Dreieck: 3 Ebenen durch die Achsen des Dreiecks und 1 Ebene in halber Höhe, also 4. Zusammen 9 + 4 + 4 = 17.", "form": "anwenden", "zaehlt": "ja", "r": 14593}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein gerades Prisma hat als Grundfläche ein regelmäßiges Vieleck mit n Ecken und genau 7 Symmetrieebenen. Wie viele Kanten hat das Prisma?"}, "o": {"wert": 18, "einheit": "Kanten"}, "h": "Wie hängt die Zahl der Symmetrieebenen eines geraden Prismas mit der Eckenzahl n der Grundfläche zusammen? Wie viele Kanten hat ein Prisma mit n-Eck?", "w": "Ein gerades Prisma über einem regelmäßigen n-Eck hat n + 1 Symmetrieebenen. Aus n + 1 = 7 folgt n = 6. Ein Prisma über einem Sechseck hat 6 Kanten unten, 6 oben und 6 senkrechte: 3 · 6 = 18 Kanten.", "form": "anwenden", "zaehlt": "ja", "r": 14594}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 213 then fehler := fehler || ('zusammen ' || gesamt || ' statt 213')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (10, 11, 31, 52, 59, 93, 94, 95, 112, 304, 305, 306, 308, 310) group by 1 order by 1;
